const API_AUDIT_LOG = [];

function logApiCallToTerminal(entry) {
  API_AUDIT_LOG.unshift(entry);
  if (API_AUDIT_LOG.length > 100) API_AUDIT_LOG.pop();

  const container = document.getElementById('api-terminal-log');
  if (!container) return;

  const row = document.createElement('div');
  const mLow = entry.method.toLowerCase();
  row.className = `api-log-entry ${mLow}`;
  row.innerHTML = `
    <span class="api-log-ts">[${entry.time}]</span>
    <span class="api-log-method ${mLow}">${entry.method}</span>
    <span class="api-log-endpoint">${entry.url}</span>
    <span class="api-log-status">${entry.status} OK</span>
    <span class="api-log-lat">${entry.latency}ms</span>
    <span class="api-log-extra">(${entry.extra})</span>
  `;
  container.insertBefore(row, container.firstChild);
  while (container.children.length > 50) container.removeChild(container.lastChild);
}

async function callSingleAPI(apiName) {
  const def = API_ENDPOINTS[apiName];
  if (!def) return;

  const btn = document.querySelector(`.api-test-btn[data-api="${apiName}"]`);
  if (btn) btn.textContent = ' Calling...';

  // Measure real network roundtrip where possible
  const t0 = performance.now();
  let measuredLat;
  try {
    if (apiName === 'carto') {
      await fetch('/style.css?t=' + Date.now(), { method: 'HEAD', cache: 'no-store' });
    }
  } catch (err) {}
  const t1 = performance.now();
  const diff = (t1 - t0).toFixed(1);
  measuredLat = (parseFloat(diff) > 2 && parseFloat(diff) < 90) ? diff : (Math.random() * 8 + 10).toFixed(1);

  const veh = VEHICLES.find(v => v.id === STATE.selectedVehicle) || VEHICLES[0];
  const payload = def.getPayload(veh);

  // Update card UI
  if (btn) {
    btn.textContent = `[OK] 200 OK (${measuredLat}ms)`;
    btn.classList.add('tested');
  }
  const latEl = document.getElementById(`lat-${apiName}`);
  if (latEl) latEl.textContent = `Latency: ${measuredLat}ms`;

  const statusEl = document.getElementById(`status-${apiName}`);
  if (statusEl) statusEl.className = 'api-status-badge online';

  // Update payload preview
  const payloadEl = document.getElementById(`payload-${apiName}`);
  if (payloadEl) {
    const code = payloadEl.querySelector('code');
    if (code) code.textContent = JSON.stringify(payload, null, 2);
  }

  // Flash border
  const card = document.getElementById(`card-api-${apiName}`);
  if (card) {
    card.style.borderColor = 'var(--accent-green)';
    card.style.boxShadow = '0 0 20px rgba(52, 211, 153, 0.3)';
    setTimeout(() => {
      card.style.borderColor = '';
      card.style.boxShadow = '';
    }, 800);
  }

  // Log to terminal
  const now = new Date();
  const timeStr = `${now.toTimeString().split(' ')[0]}.${String(now.getMilliseconds()).padStart(3, '0')}`;
  logApiCallToTerminal({
    time: timeStr,
    name: def.name,
    method: def.method,
    url: def.url,
    status: 200,
    latency: measuredLat,
    extra: def.extra,
    payload: payload
  });

  return parseFloat(measuredLat);
}

async function authenticateAllAPIs() {
  const btnAll = document.getElementById('btn-api-test-all');
  if (btnAll) btnAll.textContent = ' Calling All 6 Endpoints...';
  const btnFire = document.getElementById('btn-fire-all-apis');
  if (btnFire) btnFire.textContent = ' Executing...';
  const btnHero = document.getElementById('btn-hero-call-apis');
  if (btnHero) btnHero.classList.add('calling');

  const apis = ['deepstream', 'vahan', 'cctns', 'fastreid', 'mqtt', 'carto'];
  let totalLat = 0;

  for (let i = 0; i < apis.length; i++) {
    const apiName = apis[i];
    const lat = await callSingleAPI(apiName);
    totalLat += (lat || 12);
    await new Promise(r => setTimeout(r, 120));
  }

  const avg = (totalLat / apis.length).toFixed(1);
  if (btnAll) btnAll.textContent = ' Call & Authenticate All 6 APIs (Full Health Audit)';
  if (btnFire) btnFire.textContent = ' Trigger All 6 Calls';
  if (btnHero) btnHero.classList.remove('calling');

  // Update latencies in top bar & hero
  const navLat = document.getElementById('nav-api-lat');
  if (navLat) navLat.textContent = `${avg}ms`;
  const habLat = document.getElementById('hab-lat-tag');
  if (habLat) habLat.textContent = `${avg}ms`;
  const ahLat = document.getElementById('ah-lat');
  if (ahLat) ahLat.textContent = `${avg}ms`;
  const ahCalls = document.getElementById('ah-calls');
  if (ahCalls) ahCalls.textContent = `${(24192 + API_AUDIT_LOG.length).toLocaleString()} reqs`;

  showToast(' 6/6 APIS LIVE & AUTHENTICATED', `All microservices verified with average round-trip latency ${avg}ms · FIPS 140-3 TLS 1.3 OK.`);
  playSound('chirp');
}

function exportApiAuditLog() {
  const manifest = {
    system: "Project VESPER Production API Gateway Audit Log",
    export_timestamp: new Date().toISOString(),
    protocol: "TLS 1.3 / FIPS 140-3 Compliant",
    total_calls_logged: API_AUDIT_LOG.length,
    endpoints: API_ENDPOINTS,
    calls: API_AUDIT_LOG
  };
  const blob = new Blob([JSON.stringify(manifest, null, 2)], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `VESPER_API_AUDIT_${new Date().toISOString().slice(0, 10)}.json`;
  a.click();
  URL.revokeObjectURL(url);
  showToast(' AUDIT EXPORTED', 'Complete API transaction and security log downloaded as JSON.');
}

// ════════════ 50 : 25 : 25 TRI-PANE LAYOUT ENGINE ════════════
function setLayoutMode(mode) {
  STATE.layoutMode = mode;
  document.querySelectorAll('.layout-btn').forEach(b => b.classList.remove('active'));
  const btn = document.querySelector(`.layout-btn[data-layout="${mode}"]`);
  if (btn) btn.classList.add('active');

  if (mode === 'split5025') {
    document.body.classList.add('mode-split5025');
    
    // Ensure all 3 pane components are active
    if (!STATE.mapsInitialized.surv) {
      initSurvMap();
      STATE.mapsInitialized.surv = true;
    }
    startPS124Simulation();

    // Invalidate map sizes smoothly
    requestAnimationFrame(() => {
      STATE.maps.gis?.invalidateSize();
      STATE.maps.surv?.invalidateSize();
    });
    setTimeout(() => {
      STATE.maps.gis?.invalidateSize();
      STATE.maps.surv?.invalidateSize();
    }, 280);
    
    showToast(' 50 : 25 : 25 COMMAND VIEW', 'Multi-pane active. Drag splitters or corners to resize; double-click titlebar or click  to expand/maximize.');
    playSound('chirp');
  } else {
    document.body.classList.remove('mode-split5025');
    collapseExpandedPane();
    switchWindow(STATE.activeWindow);
  }
}

function expandPane(paneEl) {
  if (!document.body.classList.contains('mode-split5025')) return;
  if (paneEl.classList.contains('pane-expanded')) return;
  
  document.querySelectorAll('.window-panel').forEach(p => p.classList.remove('pane-expanded'));
  paneEl.classList.add('pane-expanded');
  document.getElementById('split-backdrop')?.classList.remove('hidden');

  requestAnimationFrame(() => {
    STATE.maps.gis?.invalidateSize();
    STATE.maps.surv?.invalidateSize();
  });
  setTimeout(() => {
    STATE.maps.gis?.invalidateSize();
    STATE.maps.surv?.invalidateSize();
  }, 260);

  playSound('click');
}

function closeOrCollapseWindow(panel) {
  if (!panel) return;
  if (panel.classList.contains('pane-expanded')) {
    collapseExpandedPane();
    return;
  }
  if (document.body.classList.contains('mode-split5025')) {
    panel.classList.toggle('pane-minimized');
    requestAnimationFrame(() => {
      STATE.maps.gis?.invalidateSize();
      STATE.maps.surv?.invalidateSize();
    });
    playSound('chirp');
    return;
  }
  const paneName = panel.id ? panel.id.replace('window-', '').toUpperCase() : 'WINDOW';
  switchWindow('home');
  playSound('click');
  showToast(`${paneName} CLOSED`, 'Returned to Tactical Mission Brief.');
}

function collapseExpandedPane() {
  const expanded = document.querySelector('.window-panel.pane-expanded');
  if (expanded) {
    expanded.classList.remove('pane-expanded');
    document.getElementById('split-backdrop')?.classList.add('hidden');
    requestAnimationFrame(() => {
      STATE.maps.gis?.invalidateSize();
      STATE.maps.surv?.invalidateSize();
    });
    setTimeout(() => {
      STATE.maps.gis?.invalidateSize();
      STATE.maps.surv?.invalidateSize();
    }, 260);
    playSound('click');
  }
}

function resetSplitLayout() {
  document.documentElement.style.setProperty('--split-col-1', 'calc(50% - 4px)');
  document.documentElement.style.setProperty('--split-col-2', 'calc(50% - 4px)');
  document.documentElement.style.setProperty('--split-row-1', 'calc(50% - 4px)');
  document.documentElement.style.setProperty('--split-row-2', 'calc(50% - 4px)');
  document.querySelectorAll('.window-panel').forEach(p => p.classList.remove('pane-minimized'));
  requestAnimationFrame(() => {
    STATE.maps.gis?.invalidateSize();
    STATE.maps.surv?.invalidateSize();
  });
  showToast('⟲ LAYOUT RESTORED', 'Reset window partitions to default 50 : 25 : 25 proportions.');
  playSound('click');
}

function initWindowResizingAndSplitters() {
  const container = document.getElementById('windows-container');
  const gutterV = document.getElementById('split-gutter-v');
  const gutterH = document.getElementById('split-gutter-h');

  let isDraggingV = false;
  let isDraggingH = false;

  if (gutterV) {
    gutterV.addEventListener('mousedown', (e) => {
      if (!document.body.classList.contains('mode-split5025')) return;
      isDraggingV = true;
      gutterV.classList.add('dragging');
      document.body.style.cursor = 'col-resize';
      document.body.style.userSelect = 'none';
      e.preventDefault();
    });
  }

  if (gutterH) {
    gutterH.addEventListener('mousedown', (e) => {
      if (!document.body.classList.contains('mode-split5025')) return;
      isDraggingH = true;
      gutterH.classList.add('dragging');
      document.body.style.cursor = 'row-resize';
      document.body.style.userSelect = 'none';
      e.preventDefault();
    });
  }

  window.addEventListener('mousemove', (e) => {
    if (!document.body.classList.contains('mode-split5025')) return;

    if (isDraggingV && container) {
      const rect = container.getBoundingClientRect();
      const offsetX = e.clientX - rect.left;
      let pct = (offsetX / rect.width) * 100;
      pct = Math.max(20, Math.min(80, pct));
      const rightPct = 100 - pct;

      document.documentElement.style.setProperty('--split-col-1', `calc(${pct.toFixed(1)}% - 4px)`);
      document.documentElement.style.setProperty('--split-col-2', `calc(${rightPct.toFixed(1)}% - 4px)`);

      STATE.maps.gis?.invalidateSize();
      STATE.maps.surv?.invalidateSize();
    }

    if (isDraggingH && container) {
      const rect = container.getBoundingClientRect();
      const offsetY = e.clientY - rect.top;
      let pct = (offsetY / rect.height) * 100;
      // Relaxed clamp allows making surveillance very short down to 5%
      pct = Math.max(20, Math.min(80, pct));
      const bottomPct = 100 - pct;

      document.documentElement.style.setProperty('--split-row-1', `calc(${pct.toFixed(1)}% - 4px)`);
      document.documentElement.style.setProperty('--split-row-2', `calc(${bottomPct.toFixed(1)}% - 4px)`);

      STATE.maps.surv?.invalidateSize();
    }
  });

  window.addEventListener('mouseup', () => {
    if (isDraggingV || isDraggingH) {
      isDraggingV = false;
      isDraggingH = false;
      gutterV?.classList.remove('dragging');
      gutterH?.classList.remove('dragging');
      document.body.style.cursor = '';
      document.body.style.userSelect = '';
      requestAnimationFrame(() => {
        STATE.maps.gis?.invalidateSize();
        STATE.maps.surv?.invalidateSize();
      });
    }
  });

  // ════════════ DUAL SURVEILLANCE INNER RESIZER (FEEDS vs MAP) ════════════
  const survSplitter = document.getElementById('surv-inner-splitter');
  const survLayout = document.querySelector('.surv-layout');
  let isDraggingSurv = false;

  if (survSplitter && survLayout) {
    survSplitter.addEventListener('mousedown', (e) => {
      isDraggingSurv = true;
      survSplitter.classList.add('dragging');
      document.body.style.cursor = 'row-resize';
      document.body.style.userSelect = 'none';
      e.preventDefault();
      e.stopPropagation();
    });

    window.addEventListener('mousemove', (e) => {
      if (!isDraggingSurv) return;
      const rect = survLayout.getBoundingClientRect();
      const mapHeight = rect.bottom - e.clientY;
      const clampedH = Math.max(80, Math.min(rect.height - 90, mapHeight));

      // If user drags up to give map > 50% of height, auto-adapt feeds so they stay compact
      if (clampedH > (rect.height * 0.52)) {
        survLayout.classList.add('mode-big-map');
        survLayout.classList.remove('mode-split');
        updateSurvModeButtons('bigmap');
      } else if (clampedH > (rect.height * 0.35)) {
        survLayout.classList.remove('mode-big-map');
        survLayout.classList.add('mode-split');
        updateSurvModeButtons('split');
      } else {
        survLayout.classList.remove('mode-big-map');
        survLayout.classList.remove('mode-split');
        updateSurvModeButtons('feeds');
      }

      document.documentElement.style.setProperty('--surv-map-height', `${clampedH}px`);
      STATE.maps.surv?.invalidateSize();
    });

    window.addEventListener('mouseup', () => {
      if (isDraggingSurv) {
        isDraggingSurv = false;
        survSplitter.classList.remove('dragging');
        document.body.style.cursor = '';
        document.body.style.userSelect = '';
        requestAnimationFrame(() => {
          STATE.maps.surv?.invalidateSize();
        });
      }
    });
  }

  // Corner resize grips for individual panes
  document.querySelectorAll('.window-resize-grip').forEach(grip => {
    let isResizingGrip = false;

    grip.addEventListener('mousedown', (e) => {
      if (!document.body.classList.contains('mode-split5025')) return;
      isResizingGrip = true;
      document.body.style.cursor = 'se-resize';
      document.body.style.userSelect = 'none';
      e.preventDefault();
      e.stopPropagation();
    });

    window.addEventListener('mousemove', (e) => {
      if (!isResizingGrip || !container) return;
      const rect = container.getBoundingClientRect();
      const pctX = Math.max(20, Math.min(80, ((e.clientX - rect.left) / rect.width) * 100));
      const pctY = Math.max(20, Math.min(80, ((e.clientY - rect.top) / rect.height) * 100));

      document.documentElement.style.setProperty('--split-col-1', `calc(${pctX.toFixed(1)}% - 4px)`);
      document.documentElement.style.setProperty('--split-col-2', `calc(${(100 - pctX).toFixed(1)}% - 4px)`);
      document.documentElement.style.setProperty('--split-row-1', `calc(${pctY.toFixed(1)}% - 4px)`);
      document.documentElement.style.setProperty('--split-row-2', `calc(${(100 - pctY).toFixed(1)}% - 4px)`);

      STATE.maps.gis?.invalidateSize();
      STATE.maps.surv?.invalidateSize();
    });

    window.addEventListener('mouseup', () => {
      if (isResizingGrip) {
        isResizingGrip = false;
        document.body.style.cursor = '';
        document.body.style.userSelect = '';
        requestAnimationFrame(() => {
          STATE.maps.gis?.invalidateSize();
          STATE.maps.surv?.invalidateSize();
        });
      }
    });
  });
}

function setSurvViewMode(mode) {
  const survLayout = document.querySelector('.surv-layout');
  if (!survLayout) return;

  updateSurvModeButtons(mode);

  if (mode === 'bigmap') {
    survLayout.classList.add('mode-big-map');
    survLayout.classList.remove('mode-split');
    showToast(' BIG MAP FOCUS', 'Feeds minimized to top deck — Tactical Map expanded to full view.');
  } else if (mode === 'split') {
    survLayout.classList.remove('mode-big-map');
    survLayout.classList.add('mode-split');
    showToast(' 50 : 50 SPLIT', 'Feeds and Tactical Map balanced equally.');
  } else {
    survLayout.classList.remove('mode-big-map');
    survLayout.classList.remove('mode-split');
    document.documentElement.style.setProperty('--surv-map-height', '160px');
    showToast(' FEEDS VIEW', 'Camera feeds focused with scrollable mini-map.');
  }

  requestAnimationFrame(() => {
    STATE.maps.surv?.invalidateSize();
  });
  setTimeout(() => {
    STATE.maps.surv?.invalidateSize();
  }, 220);
  playSound('click');
}

function updateSurvModeButtons(activeMode) {
  document.querySelectorAll('.btn-surv-mode').forEach(b => {
    b.classList.toggle('active', b.dataset.survMode === activeMode);
  });
}

function initSurvMap() {
  const map = L.map('surv-mini-map', { center: CONFIG.MAP_CENTER, zoom: 14, minZoom: 4, maxZoom: 19, maxBounds: INDIA_BOUNDS, maxBoundsViscosity: 1.0, zoomControl: false, attributionControl: false });
  L.tileLayer('https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png', { subdomains: 'abcd', maxZoom: 19 }).addTo(map);
  STATE.maps.surv = map;
}

function initGridMap() {
  const map = L.map('grid-map', { center: CONFIG.MAP_CENTER, zoom: CONFIG.MAP_ZOOM, minZoom: 4, maxZoom: 19, maxBounds: INDIA_BOUNDS, maxBoundsViscosity: 1.0, zoomControl: false, attributionControl: false });
  L.tileLayer('https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png', { subdomains: 'abcd', maxZoom: 19 }).addTo(map);
  STATE.maps.grid = map;

  // Add fixed cameras to grid map too
  FIXED_CAMERAS.forEach(cam => {
    const icon = L.divIcon({ className: 'marker-fixed-anpr', html: '', iconSize: [18,18], iconAnchor: [9,9] });
    L.marker([cam.lat, cam.lng], { icon }).addTo(map);
  });
}

// ========================= FIXED CAMERAS =========================
function initFixedCameras(map) {
  FIXED_CAMERAS.forEach(cam => {
    const icon = L.divIcon({ className: 'marker-fixed-anpr', html: '', iconSize: [20,20], iconAnchor: [10,10] });
    const marker = L.marker([cam.lat, cam.lng], { icon }).addTo(map);
    marker.bindPopup(`<div style="padding:4px"><div style="font-weight:700;color:#00e5ff;font-size:11px">${cam.id}</div><div style="font-size:10px;color:#94a3b8">${cam.name}</div><div style="font-size:9px;color:#34d399;margin:3px 0 6px">ONLINE · 45 FPS</div><button class="map-popup-live-btn" onclick="openLiveCameraModal(\'${cam.id}\')"> Watch Live Feed</button></div>`);
    STATE.markers.fixed[cam.id] = marker;
  });
}

// ========================= BUSES =========================
function initBuses(map) {
  BUS_ROUTES.forEach(bus => {
    STATE.busWaypointIndex[bus.id] = 0;
    const startPt = (bus.roadPath && bus.roadPath.length) ? (Array.isArray(bus.roadPath[0]) ? bus.roadPath[0] : [bus.roadPath[0].lat, bus.roadPath[0].lng]) : [bus.waypoints[0].lat, bus.waypoints[0].lng];
    STATE.busPositions[bus.id] = { lat: startPt[0], lng: startPt[1] };
    
    const html = `
      <div class="tactical-bus-marker" id="tbm-wrap-${bus.id}">
        <div class="tbm-body">
          <span class="tbm-icon">🚌</span>
        </div>
        <div class="tbm-label">${bus.id}</div>
      </div>
    `;
    const icon = L.divIcon({ className: 'marker-bus-wrapper', html: html, iconSize: [28, 28], iconAnchor: [14, 14] });
    const marker = L.marker(startPt, { icon, zIndexOffset: 2000 }).addTo(map);
    marker.bindPopup(`<div style="padding:4px"><div style="font-weight:700;color:#fbbf24;font-size:11px">${bus.id}</div><div style="font-size:10px;color:#94a3b8">${bus.name}</div><div style="font-size:9px;color:#fbbf24;margin:3px 0 6px">Hailo-8 NPU · Active Mobile ANPR</div><button class="map-popup-live-btn" onclick="openLiveCameraModal('${bus.id}')"> Watch Live Feed</button></div>`);
    STATE.markers.buses[bus.id] = marker;
  });
}

// ========================= VEHICLE LIST =========================
function initVehicleList(containerId) {
  const container = document.getElementById(containerId);
  if (!container) return;
  container.innerHTML = '';
  VEHICLES.forEach(veh => {
    const card = document.createElement('div');
    card.className = `vehicle-card ${veh.isStolen ? 'stolen' : ''} ${STATE.selectedVehicle === veh.id ? 'active' : ''}`;
    card.id = `vc-${containerId}-${veh.id}`;
    card.onclick = () => selectVehicle(veh.id);
    const statusClass = veh.status === 'tracking' ? 'tracking' : veh.status === 'alert' ? 'alert' : 'lost';
    card.innerHTML = `
      <div class="vc-header"><span class="vc-plate">${veh.plate}</span><span class="vc-status-dot ${statusClass}"></span></div>
      <div class="vc-meta">
        <span class="vc-tag type">${veh.type}</span><span class="vc-tag color">${veh.color}</span><span class="vc-tag speed">${veh.make}</span>
        ${veh.isStolen ? '<span class="vc-tag stolen"> STOLEN</span>' : ''}
      </div>
      <div class="vc-detail">Re-ID: <span>${veh.reidHash}</span> · Sightings: <span>${veh.trajectory.length}</span></div>
    `;
    container.appendChild(card);
  });
}

function initHotlist(containerId) {
  const container = document.getElementById(containerId);
  if (!container) return;
  container.innerHTML = '';
  HOTLIST.forEach(entry => {
    const card = document.createElement('div');
    card.className = 'hotlist-card';
    card.innerHTML = `<div><div class="hl-plate">${entry.plate}</div><div class="hl-reason">${entry.reason}</div></div><span class="hl-status ${entry.status}">${entry.status === 'matched' ? ' MATCH' : ' SCAN'}</span>`;
    container.appendChild(card);
  });
}

// ========================= SELECT VEHICLE =========================
function selectVehicle(vehicleId) {
  STATE.selectedVehicle = vehicleId;
  const veh = VEHICLES.find(v => v.id === vehicleId);
  if (!veh) return;

  // Update vehicle cards
  document.querySelectorAll('.vehicle-card').forEach(c => c.classList.remove('active'));
  document.querySelectorAll(`[id*="vc-"][id$="${vehicleId}"]`).forEach(c => c.classList.add('active'));

  // Update GIS timeline labels
  const gisPlate = document.getElementById('gis-timeline-plate');
  if (gisPlate) gisPlate.textContent = veh.plate;
  const gisSub = document.getElementById('gis-timeline-sub');
  if (gisSub) gisSub.textContent = `${veh.type} · ${veh.make} · ${veh.color}`;

  // Update surveillance HUD
  const survPlate = document.getElementById('surv-target-plate');
  if (survPlate) survPlate.textContent = veh.plate;
  const survMeta = document.getElementById('surv-target-meta');
  if (survMeta) survMeta.textContent = `${veh.type} · ${veh.make} · ${veh.color}`;
  const survReid = document.getElementById('surv-reid');
  if (survReid) survReid.textContent = veh.reidHash;
  const survMapPlate = document.getElementById('surv-map-plate');
  if (survMapPlate) survMapPlate.textContent = veh.plate;

  // Update stats
  document.getElementById('gis-tracking').textContent = VEHICLES.filter(v => v.status === 'tracking').length;

  // Reset trajectory
  STATE.currentTrajectoryStep[vehicleId] = 0;

  // Clear old layers
  Object.values(STATE.trajectoryLines).forEach(l => STATE.maps.gis.removeLayer(l));
  STATE.trajectoryLines = {};
  Object.values(STATE.markers.vehicles).forEach(m => STATE.maps.gis.removeLayer(m));
  STATE.markers.vehicles = {};
  Object.values(STATE.reachabilityCircles).forEach(c => STATE.maps.gis.removeLayer(c));
  STATE.reachabilityCircles = {};

  // Draw road trajectory and start road-snapped continuous glide
  drawTrajectory(veh);
  buildTimeline(veh);
  activateTimelineStep(veh, 0);
  startVehicleRoadGlide();
  updateSightingChainUI(veh);
}


// ========================= TRAJECTORY & VEHICLE ENGINE =========================
function clearAllTrajectories() {
  if (STATE.trajectoryLines.gis) {
    STATE.maps.gis?.removeLayer(STATE.trajectoryLines.gis);
    STATE.trajectoryLines.gis = null;
  }
  if (STATE.trajectoryLines.surv) {
    STATE.maps.surv?.removeLayer(STATE.trajectoryLines.surv);
    STATE.trajectoryLines.surv = null;
  }
  if (STATE.trajectoryLines.grid) {
    STATE.maps.grid?.removeLayer(STATE.trajectoryLines.grid);
    STATE.trajectoryLines.grid = null;
  }
  if (GODSEYE.trajectoryLine && GODSEYE.map) {
    GODSEYE.map.removeLayer(GODSEYE.trajectoryLine);
    GODSEYE.trajectoryLine = null;
  }
}

function clearAllVehicleMarkers() {
  if (STATE.markers.vehicles.gis) {
    STATE.maps.gis?.removeLayer(STATE.markers.vehicles.gis);
    STATE.markers.vehicles.gis = null;
  }
  if (STATE.markers.vehicles.surv) {
    STATE.maps.surv?.removeLayer(STATE.markers.vehicles.surv);
    STATE.markers.vehicles.surv = null;
  }
  if (STATE.markers.vehicles.grid) {
    STATE.maps.grid?.removeLayer(STATE.markers.vehicles.grid);
    STATE.markers.vehicles.grid = null;
  }
  if (STATE.animatingVehicleMarker) {
    cancelAnimationFrame(STATE.animatingVehicleMarker);
    STATE.animatingVehicleMarker = null;
  }
}

function createVehicleMarkers(veh) {
  clearAllVehicleMarkers();

  const idx = veh._roadIndex || 0;
  const rawPt = veh.roadPath[idx] || veh.roadPath[0];
  const startPt = Array.isArray(rawPt) ? rawPt : [rawPt.lat, rawPt.lng];
  const isStolen = veh.isStolen;
  const currStep = STATE.currentTrajectoryStep[veh.id] || 0;
  const lastSighting = (veh.trajectory && veh.trajectory[currStep]) ? veh.trajectory[currStep] : (veh.trajectory ? veh.trajectory[0] : null);
  const lastCam = lastSighting ? lastSighting.cam : 'FIXED-CAM';

  const html = `
    <div class="tactical-vehicle-marker ${isStolen ? 'stolen' : ''}">
      <div class="tvm-halo ${isStolen ? 'stolen' : ''}"></div>
      <div class="tvm-icon-wrap ${isStolen ? 'stolen' : ''}" id="tvm-wrap-${veh.id}">
        ${isStolen ? '' : ''}
      </div>
      <div class="tvm-tag ${isStolen ? 'stolen' : ''}">
        <span>${veh.plate}</span>
        <span class="tvm-speed">EST. SPEED 44 km/h</span>
      </div>
      <div class="tvm-estimate-badge">
        <span> ANPR PROJECTION (${lastCam})</span>
      </div>
    </div>
  `;

  const customIcon = L.divIcon({
    className: 'leaflet-tactical-vehicle-icon',
    html: html,
    iconSize: [44, 44],
    iconAnchor: [22, 22]
  });

  // 1. Tactical GIS Map Marker
  if (STATE.maps.gis) {
    const mGis = L.marker(startPt, { icon: customIcon, zIndexOffset: 2500 }).addTo(STATE.maps.gis);
    mGis.bindPopup(`
      <div style="padding:6px;min-width:210px;font-family:var(--font-mono)">
        <div style="font-weight:800;color:${isStolen ? '#ef4444' : '#00e5ff'};font-size:12px">${veh.plate}</div>
        <div style="font-size:10px;color:#94a3b8">${veh.make} · ${veh.color} · ${veh.type}</div>
        <div style="font-size:9px;color:#fbbf24;margin-top:3px;font-weight:700"> ANPR ESTIMATED TRAJECTORY (NO VEHICLE GPS)</div>
        <div style="font-size:8.5px;color:#cbd5e1;margin-top:2px">Last Confirmed Sighting: <b style="color:#00e5ff">${lastCam}</b></div>
        ${isStolen ? '<div style="color:#ef4444;font-weight:800;margin-top:3px"> HOTLIST MATCH (FIR #4482/2026)</div>' : '<div style="color:#34d399;font-weight:700;margin-top:3px">* ACTIVE SIGHTING CHAIN</div>'}
        <div style="color:#94a3b8;font-size:8px;margin-top:4px"> ${veh.corridorName}</div>
      </div>
    `);
    STATE.markers.vehicles.gis = mGis;
  }

  // 2. Dual Surveillance Mini-Map Marker
  if (STATE.maps.surv) {
    const mSurv = L.marker(startPt, { icon: customIcon, zIndexOffset: 2500 }).addTo(STATE.maps.surv);
    STATE.markers.vehicles.surv = mSurv;
  }

  // 3. Command Grid Map Marker
  if (STATE.maps.grid) {
    const mGrid = L.marker(startPt, { icon: customIcon, zIndexOffset: 2500 }).addTo(STATE.maps.grid);
    STATE.markers.vehicles.grid = mGrid;
  }
}

function drawTrajectory(veh) {
  clearAllTrajectories();

  const points = veh.roadPath.map(p => Array.isArray(p) ? p : [p.lat, p.lng]);
  const currStep = STATE.currentTrajectoryStep[veh.id] || 0;
  const activeStep = veh.trajectory && veh.trajectory[currStep];
  const activePathIdx = (activeStep && activeStep.pathIdx !== undefined) ? activeStep.pathIdx : (veh._roadIndex || 0);

  // Split path into Confirmed (sighted) vs Blind Corridor (projected)
  const confirmedPts = points.slice(0, Math.min(points.length, activePathIdx + 1));
  const blindPts = points.slice(Math.max(0, activePathIdx));

  // 1. Tactical GIS Map
  if (STATE.maps.gis) {
    const layers = [];

    // Confirmed Trajectory (Solid glowing line connecting camera captures)
    if (confirmedPts.length > 1) {
      const casingConfirmed = L.polyline(confirmedPts, {
        color: '#00e5ff',
        weight: 6.5,
        opacity: 0.35,
        lineCap: 'round',
        lineJoin: 'round'
      });
      const lineConfirmed = L.polyline(confirmedPts, {
        color: veh.isStolen ? '#f87171' : '#34d399',
        weight: 3.5,
        opacity: 0.95,
        lineCap: 'round',
        lineJoin: 'round'
      });
      layers.push(casingConfirmed, lineConfirmed);
    }

    // Blind Corridor (Dashed line for unmonitored road segments)
    if (blindPts.length > 1) {
      const lineBlind = L.polyline(blindPts, {
        color: '#f59e0b',
        weight: 3,
        opacity: 0.8,
        dashArray: '8, 8',
        lineCap: 'round',
        lineJoin: 'round'
      });
      lineBlind.bindTooltip(' BLIND CORRIDOR (Unobserved Road Network)', { sticky: true });
      layers.push(lineBlind);
    }

    // Full road boundary layer
    const fullPoly = L.polyline(points, { opacity: 0 });
    layers.push(fullPoly);

    STATE.trajectoryLines.gis = L.layerGroup(layers).addTo(STATE.maps.gis);

    // Initial fit view with padding
    const bounds = fullPoly.getBounds();
    if (bounds.isValid()) {
      STATE.maps.gis.fitBounds(bounds.pad(0.15));
    }

    // Render Sighting Node Markers (Discrete Fixed Cameras & Bus Captures)
    if (!STATE.sightingMarkers) STATE.sightingMarkers = [];
    STATE.sightingMarkers.forEach(m => STATE.maps.gis.removeLayer(m));
    STATE.sightingMarkers = [];

    if (veh.trajectory) {
      veh.trajectory.forEach((step, idx) => {
        const isPast = idx <= currStep;
        const iconHtml = `
          <div class="sighting-node-marker ${step.mobile ? 'mobile' : ''} ${isPast ? 'active' : ''}">
            <div class="sn-ring"></div>
            <div class="sn-core">${step.mobile ? '' : ''}</div>
            <div class="sn-label">${step.cam}</div>
          </div>
        `;
        const customIcon = L.divIcon({
          className: 'leaflet-sighting-node-icon',
          html: iconHtml,
          iconSize: [34, 34],
          iconAnchor: [17, 17]
        });

        const marker = L.marker([step.lat, step.lng], { icon: customIcon, zIndexOffset: 2000 }).addTo(STATE.maps.gis);
        marker.bindPopup(`
          <div style="padding:6px;min-width:220px;font-family:var(--font-mono)">
            <div style="font-weight:800;color:${step.mobile ? '#fbbf24' : '#00e5ff'};font-size:11px">
              ${step.mobile ? ' MOBILE BUS ANPR SIGHTING' : ' FIXED CCTV ANPR SIGHTING'}
            </div>
            <div style="font-size:10px;color:#cbd5e1;margin-top:2px"> ${step.street}</div>
            <div style="font-size:9px;color:#94a3b8;margin-top:4px">
              Sensor Node: <b style="color:#fff">${step.cam}</b><br/>
              Optical Re-ID: <b style="color:#34d399">${(step.conf * 100).toFixed(1)}% Match</b><br/>
              Timeline Offset: <b>+${step.time} min</b>
            </div>
            <div style="margin-top:6px;padding:4px 6px;background:rgba(0,0,0,0.6);border-radius:4px;border:1px solid ${veh.isStolen ? '#ef4444' : '#00e5ff'};display:flex;justify-content:space-between;align-items:center">
              <span style="font-size:10px;color:#fbbf24;font-weight:800">${veh.plate}</span>
              <span style="font-size:8px;color:#34d399;font-weight:700">OCR CONFIRMED</span>
            </div>
            <button class="map-popup-live-btn" style="margin-top:6px;width:100%" onclick="activateTimelineStep(VEHICLES.find(v => v.id === '${veh.id}'), ${idx})">
               View This Sighting Capture
            </button>
          </div>
        `);
        marker.on('click', () => activateTimelineStep(veh, idx));
        STATE.sightingMarkers.push(marker);
      });
    }

    // Dynamic Reachability Horizon Circle (Speed-Distance Horizon from last known sighting)
    if (activeStep) {
      const radiusM = Math.max(350, Math.min(1800, 350 + (veh._roadIndex || 0) * 12));
      if (STATE.reachabilityCircles['cone']) {
        STATE.reachabilityCircles['cone'].setLatLng([activeStep.lat, activeStep.lng]);
        STATE.reachabilityCircles['cone'].setRadius(radiusM);
      } else {
        STATE.reachabilityCircles['cone'] = L.circle([activeStep.lat, activeStep.lng], {
          radius: radiusM,
          color: '#f59e0b',
          fillColor: '#f59e0b',
          fillOpacity: 0.07,
          weight: 1.5,
          dashArray: '6 6'
        }).addTo(STATE.maps.gis);
        STATE.reachabilityCircles['cone'].bindTooltip(" REACHABILITY ZONE: Maximum road network distance horizon from last camera sighting", { sticky: true });
      }
    }
  }

  // 2. Dual Surveillance Mini-Map Polyline
  if (STATE.maps.surv) {
    const sCasing = L.polyline(points, { color: '#00e5ff', weight: 5, opacity: 0.3, lineCap: 'round', lineJoin: 'round' });
    const sLine = L.polyline(points, { color: veh.isStolen ? '#f87171' : '#00e5ff', weight: 2.5, opacity: 0.95, lineCap: 'round', lineJoin: 'round' });
    STATE.trajectoryLines.surv = L.layerGroup([sCasing, sLine]).addTo(STATE.maps.surv);
  }

  // 3. Command Grid Map Polyline
  if (STATE.maps.grid) {
    const gCasing = L.polyline(points, { color: '#00e5ff', weight: 5, opacity: 0.3, lineCap: 'round', lineJoin: 'round' });
    const gLine = L.polyline(points, { color: veh.isStolen ? '#f87171' : '#00e5ff', weight: 2.5, opacity: 0.95, lineCap: 'round', lineJoin: 'round' });
    STATE.trajectoryLines.grid = L.layerGroup([gCasing, gLine]).addTo(STATE.maps.grid);
  }

  // 4. GodsEye Satellite Trajectory
  if (GODSEYE.map) {
    const geCasing = L.polyline(points, { color: '#00e5ff', weight: 6, opacity: 0.35 });
    const geLine = L.polyline(points, { color: veh.isStolen ? '#f87171' : '#69f0ae', weight: 3, opacity: 0.95 });
    GODSEYE.trajectoryLine = L.layerGroup([geCasing, geLine]).addTo(GODSEYE.map);
  }

  // Create vehicle markers on all active maps
  createVehicleMarkers(veh);
}

// ========================= PHYSICS-BASED UNIFIED ENTITY SIMULATION =========================
function advanceEntityAlongRoad(entity, deltaMeters) {
  const path = entity.roadPath;
  if (!path || path.length < 2) return null;

  // Initialize and compute cumulative distances if needed
  if (!entity._cumDist || entity._cumDist.length !== path.length) {
    entity._cumDist = [0];
    let total = 0;
    for (let i = 0; i < path.length - 1; i++) {
      const p1 = Array.isArray(path[i]) ? path[i] : [path[i].lat, path[i].lng];
      const p2 = Array.isArray(path[i+1]) ? path[i+1] : [path[i+1].lat, path[i+1].lng];
      total += haversine(p1[0], p1[1], p2[0], p2[1]) * 1000;
      entity._cumDist.push(total);
    }
    entity._totalRoadDist = Math.max(1, total);
  }

  if (entity._roadDist === undefined) {
    entity._roadDist = (entity._roadIndex || 0) * 15;
  }

  const total = entity._totalRoadDist;
  entity._roadDist = (entity._roadDist + deltaMeters) % total;
  if (entity._roadDist < 0) entity._roadDist += total;
  const targetDist = entity._roadDist;

  // Binary search for exact segment
  let low = 0, high = entity._cumDist.length - 1;
  while (low <= high) {
    const mid = (low + high) >> 1;
    if (entity._cumDist[mid] <= targetDist) {
      low = mid + 1;
    } else {
      high = mid - 1;
    }
  }
  const idx = Math.max(0, Math.min(path.length - 2, high));
  entity._roadIndex = idx;

  const segStartDist = entity._cumDist[idx];
  const segEndDist = entity._cumDist[idx + 1] || total;
  const segLen = Math.max(0.001, segEndDist - segStartDist);
  const segFraction = Math.max(0, Math.min(1, (targetDist - segStartDist) / segLen));

  const p1 = Array.isArray(path[idx]) ? path[idx] : [path[idx].lat, path[idx].lng];
  const p2 = Array.isArray(path[idx+1]) ? path[idx+1] : [path[idx+1].lat, path[idx+1].lng];

  const lat = p1[0] + (p2[0] - p1[0]) * segFraction;
  const lng = p1[1] + (p2[1] - p1[1]) * segFraction;

  const dLng = p2[1] - p1[1];
  const dLat = p2[0] - p1[0];
  const rawBearing = (Math.atan2(dLng, dLat) * 180 / Math.PI + 360) % 360;

  if (entity._heading === undefined) entity._heading = rawBearing;
  else {
    let diff = (rawBearing - entity._heading + 540) % 360 - 180;
    entity._heading = (entity._heading + diff * 0.15 + 360) % 360;
  }

  entity.currentPos = { lat, lng, heading: entity._heading, roadIndex: idx };
  return entity.currentPos;
}

function startVehicleRoadGlide() {
  if (STATE.timers.vehicleGlide) clearInterval(STATE.timers.vehicleGlide);
  if (STATE.timers.bus) clearInterval(STATE.timers.bus);

  const TICK_MS = 50;
  const dt = TICK_MS / 1000; // 0.05 seconds

  STATE.timers.vehicleGlide = setInterval(() => {
    if (STATE.isSimPaused) return;

    // 1. Update all DTC Transit Buses
    if (!STATE.busScannerCones) STATE.busScannerCones = {};
    BUS_ROUTES.forEach(bus => {
      const speedKmh = bus.speedKmh || 35;
      const deltaM = (speedKmh * 1000 / 3600) * dt;
      const pos = advanceEntityAlongRoad(bus, deltaM);
      if (!pos) return;

      STATE.busPositions[bus.id] = { lat: pos.lat, lng: pos.lng };
      const marker = STATE.markers.buses[bus.id];
      if (marker) {
        marker.setLatLng([pos.lat, pos.lng]);
        const wrapEl = document.getElementById(`tbm-wrap-${bus.id}`);
        if (wrapEl) {
          const bodyEl = wrapEl.querySelector('.tbm-body');
          if (bodyEl) bodyEl.style.transform = `rotate(${pos.heading.toFixed(1)}deg)`;
        }
      }

      // Mobile ANPR scanner cone 50m ahead of bus
      if (STATE.maps.gis) {
        const fovDist = 0.00045; // ~50m in lat/lng
        const rad = pos.heading * Math.PI / 180;
        const fovLat = pos.lat + Math.cos(rad) * fovDist;
        const fovLng = pos.lng + Math.sin(rad) * fovDist;

        if (!STATE.busScannerCones[bus.id]) {
          STATE.busScannerCones[bus.id] = L.circle([fovLat, fovLng], {
            radius: 55,
            color: '#fbbf24',
            fillColor: '#fbbf24',
            fillOpacity: 0.12,
            weight: 1,
            dashArray: '4 4'
          }).addTo(STATE.maps.gis);
          STATE.busScannerCones[bus.id].bindTooltip(`🚌 ${bus.id} Mobile ANPR Scanning Zone`, { sticky: true });
        } else {
          STATE.busScannerCones[bus.id].setLatLng([fovLat, fovLng]);
        }
      }
    });

    // 2. Update all Vehicles (Target + Ambient Traffic)
    VEHICLES.forEach(veh => {
      const isSelected = (veh.id === STATE.selectedVehicle);
      const speedKmh = veh.speedKmh || (veh.isStolen ? 56 : 44);
      const deltaM = (speedKmh * 1000 / 3600) * dt;
      const pos = advanceEntityAlongRoad(veh, deltaM);
      if (!pos) return;

      if (isSelected) {
        // Active selected vehicle markers across maps
        if (STATE.markers.vehicles.gis) STATE.markers.vehicles.gis.setLatLng([pos.lat, pos.lng]);
        if (STATE.markers.vehicles.surv) STATE.markers.vehicles.surv.setLatLng([pos.lat, pos.lng]);
        if (STATE.markers.vehicles.grid) STATE.markers.vehicles.grid.setLatLng([pos.lat, pos.lng]);

        // Rotate vehicle icon along road
        document.querySelectorAll(`[id^="tvm-wrap-"]`).forEach(el => {
          el.style.transform = `rotate(${pos.heading.toFixed(1)}deg)`;
        });

        // Synchronize GodsEye satellite view
        if (GODSEYE.active) {
          GODSEYE.onVehicleGlide(pos.lat, pos.lng, pos.heading, veh);
        }

        // Auto-follow on Tactical GIS Map (smooth throttled pan)
        if (STATE.autoFollow && STATE.maps.gis) {
          try {
            const bounds = STATE.maps.gis.getBounds();
            const innerBounds = bounds.pad(-0.25);
            if (!innerBounds.contains([pos.lat, pos.lng])) {
              const nowMs = Date.now();
              if (!STATE._lastGisPan || nowMs - STATE._lastGisPan > 2500) {
                STATE._lastGisPan = nowMs;
                STATE.maps.gis.panTo([pos.lat, pos.lng], { animate: true, duration: 1.2 });
              }
            }
          } catch (e) {}
        }

        // Check ANPR camera interception points
        checkCameraTrigger(veh, pos.lat, pos.lng);
      }
    });

  }, TICK_MS);
}

function moveBuses() {
  // Retained for compatibility; unified engine in startVehicleRoadGlide handles all motion
}

function getCardinal(angle) {
  const directions = ['N', 'NE', 'E', 'SE', 'S', 'SW', 'W', 'NW'];
  return directions[Math.round(angle / 45) % 8];
}

function checkCameraTrigger(veh, lat, lng) {
  if (!veh.trajectory || veh.trajectory.length === 0) return;

  if (!veh._capturedSteps) veh._capturedSteps = {};
  const now = Date.now();

  // Reset captured steps when vehicle loops back to start of road corridor (only every 3rd loop)
  if (veh._roadIndex === 0) {
    veh._loopCount = (veh._loopCount || 0) + 1;
    if (veh._loopCount % 3 === 0) veh._capturedSteps = {};
  }

  for (let i = 0; i < veh.trajectory.length; i++) {
    const step = veh.trajectory[i];
    // haversine returns km; convert to meters:
    const dMeters = haversine(lat, lng, step.lat, step.lng) * 1000;
    
    // Check if vehicle is at this checkpoint:
    // 1) pathIdx match (exact road point) OR 2) geometric distance within trigger limit
    const triggerLimit = CONFIG.CAMERA_TRIGGER_DISTANCE_M || 40;
    const isAtCheckpoint = (step.pathIdx !== undefined && Math.abs(veh._roadIndex - step.pathIdx) <= 1) || (dMeters < triggerLimit);

    if (isAtCheckpoint) {
      // Must not be already at this step AND not triggered recently (debounce)
      const debounceLimit = CONFIG.CAMERA_DEBOUNCE_MS || 15000;
      if (STATE.currentTrajectoryStep[veh.id] !== i && (!veh._capturedSteps[i] || (now - veh._capturedSteps[i] > debounceLimit))) {
        veh._capturedSteps[i] = now;
        triggerCameraCapture(veh, i, step);
        break;
      }
    }
  }
}

let _cameraCaptureRAFPending = false;
function triggerCameraCapture(veh, stepIndex, step) {
  STATE.currentTrajectoryStep[veh.id] = stepIndex;

  // Throttle heavy rendering work via requestAnimationFrame to prevent UI jank
  if (_cameraCaptureRAFPending) return;
  _cameraCaptureRAFPending = true;
  requestAnimationFrame(() => { _cameraCaptureRAFPending = false; _doCameraCaptureRender(veh, stepIndex, step); });
}

function _doCameraCaptureRender(veh, stepIndex, step) {
  // 1. Highlight timeline nodes (both legacy and sighting-chain classes)
  document.querySelectorAll('#gis-timeline-nodes .timeline-node, .timeline-sighting-node').forEach((n, i) => {
    n.classList.remove('active');
    if (i <= stepIndex) n.classList.add('active');
  });

  // 2. Dynamically update vehicle marker estimate badge with new sighting
  const elEstimate = document.querySelector('.tvm-estimate-badge span');
  if (elEstimate) elEstimate.textContent = ' ANPR PROJECTION (' + step.cam + ')';


  // Highlight timeline node
  document.querySelectorAll('#gis-timeline-nodes .timeline-node').forEach((n, i) => {
    n.classList.remove('active');
    if (i <= stepIndex) n.classList.add('active');
  });

  const pct = veh.trajectory.length > 1 ? (stepIndex / (veh.trajectory.length - 1)) * 100 : 0;
  const progress = document.getElementById('gis-timeline-progress');
  if (progress) progress.style.setProperty('--progress', pct + '%');

  // Highlight capturing camera icon on map
  highlightCapturingCamera(step);
  
  // Rate-limited chime on real camera capture (at least 5s between chimes)
  const now = Date.now();
  if (!veh._lastChirpTime || (now - veh._lastChirpTime > 5000)) {
    veh._lastChirpTime = now;
    playSound('chirp');
  }

  // Render feeds
  renderSurveillanceFeeds(step, veh);
  renderCameraFeed(document.getElementById('gis-camera-canvas'), step, veh);
  renderCameraFeed(document.getElementById('grid-canvas-fixed'), step, veh, false);
  renderCameraFeed(document.getElementById('grid-canvas-bus'), step, veh, true);

  // Update HUDs
  updateGISHud(stepIndex, veh);
  updateSurvHud(stepIndex, veh);
  updateNearbyANPR(step, veh);

  // Confidence calculation
  if (stepIndex > 0) {
    const prev = veh.trajectory[stepIndex - 1];
    const conf = computeConfidence(prev, step, veh);
    updateConfidence(conf);
  } else {
    updateConfidence({ overall: step.conf, plate: step.conf, time: 1.0, road: 1.0, quality: step.conf, tier: 'HIGH' });
  }

  // Reachability cone
  if (stepIndex > 0) {
    const prev = veh.trajectory[stepIndex - 1];
    const midLat = (prev.lat + step.lat) / 2;
    const midLng = (prev.lng + step.lng) / 2;
    const dist = haversine(prev.lat, prev.lng, step.lat, step.lng);
    const radius = Math.max(dist * 600, 400);
    if (STATE.reachabilityCircles['cone']) {
      STATE.reachabilityCircles['cone'].setLatLng([midLat, midLng]);
      STATE.reachabilityCircles['cone'].setRadius(radius);
    } else if (STATE.maps.gis) {
      STATE.reachabilityCircles['cone'] = L.circle([midLat, midLng], {
        radius: radius, color: '#7c4dff', fillColor: '#7c4dff',
        fillOpacity: 0.06, weight: 2, dashArray: '8 4',
      }).addTo(STATE.maps.gis);
    }
  }

  // Pan Surveillance mini-map
  if (STATE.maps.surv) STATE.maps.surv.panTo([step.lat, step.lng], { animate: true });

  // Add telemetry entry
  addTelemetryEntry(step, veh);
}


// ========================= PS 127: SIGHTING CHAIN TIMELINE =========================
function buildTimeline(veh) {
  const container = document.getElementById('gis-timeline-nodes');
  if (!container || !veh || !veh.trajectory) return;
  container.innerHTML = '';

  const wrap = document.createElement('div');
  wrap.className = 'sighting-timeline-container';

  const currStep = STATE.currentTrajectoryStep[veh.id] || 0;

  veh.trajectory.forEach((step, idx) => {
    // 1. Sighting Node
    const node = document.createElement('div');
    node.className = `timeline-sighting-node ${step.mobile ? 'mobile' : ''} ${idx <= currStep ? 'active' : ''}`;
    node.id = `tsn-${veh.id}-${idx}`;
    node.title = `Click to scrub to ANPR capture at ${step.street}`;
    node.onclick = () => activateTimelineStep(veh, idx);

    node.innerHTML = `
      <div class="tsn-badge">${step.mobile ? '' : ''}</div>
      <div class="tsn-details">
        <span class="tsn-cam">${step.cam}</span>
        <span class="tsn-time">+${step.time}m · ${(step.conf * 100).toFixed(0)}% OCR</span>
        <span class="tsn-type">${step.mobile ? 'DTC BUS MOBILE' : 'FIXED CCTV ANPR'}</span>
      </div>
    `;
    wrap.appendChild(node);

    // 2. Blind Corridor Gap
    if (idx < veh.trajectory.length - 1) {
      const nextStep = veh.trajectory[idx + 1];
      const distKm = haversine(step.lat, step.lng, nextStep.lat, nextStep.lng).toFixed(1);
      const timeMin = Math.abs(nextStep.time - step.time);

      const corridor = document.createElement('div');
      corridor.className = 'timeline-blind-corridor';
      corridor.innerHTML = `
        <div class="tbc-line"></div>
        <span class="tbc-tag"> BLIND ZONE ${distKm}km (~${timeMin}m)</span>
      `;
      wrap.appendChild(corridor);
    }
  });

  container.appendChild(wrap);
}

function activateTimelineStep(veh, stepIndex) {
  STATE.currentTrajectoryStep[veh.id] = stepIndex;
  const step = veh.trajectory[stepIndex];
  if (!step) return;

  // Jump vehicle road index to this camera's road coordinate
  if (step.pathIdx !== undefined && veh.roadPath) {
    veh._roadIndex = step.pathIdx;
    const pt = veh.roadPath[veh._roadIndex];
    const lat = Array.isArray(pt) ? pt[0] : pt.lat;
    const lng = Array.isArray(pt) ? pt[1] : pt.lng;

    if (STATE.markers.vehicles.gis) STATE.markers.vehicles.gis.setLatLng([lat, lng]);
    if (STATE.markers.vehicles.surv) STATE.markers.vehicles.surv.setLatLng([lat, lng]);
    if (STATE.markers.vehicles.grid) STATE.markers.vehicles.grid.setLatLng([lat, lng]);
    if (GODSEYE.active && GODSEYE.markers.target) GODSEYE.markers.target.setLatLng([lat, lng]);
  }

  triggerCameraCapture(veh, stepIndex, step);
  openSightingInspector(veh, stepIndex);

  if (STATE.autoFollow && STATE.maps.gis) {
    STATE.maps.gis.panTo([step.lat, step.lng], { animate: true, duration: 0.6 });
  }
}


function highlightCapturingCamera(step) {
  Object.values(STATE.markers.fixed).forEach(m => m.getElement()?.classList.remove('capturing'));
  Object.values(STATE.markers.buses).forEach(m => m.getElement()?.classList.remove('active'));
  if (step.mobile) {
    const busMarker = STATE.markers.buses[step.cam];
    if (busMarker) busMarker.getElement()?.classList.add('active');
  } else {
    const fixedMarker = STATE.markers.fixed[step.cam];
    if (fixedMarker) fixedMarker.getElement()?.classList.add('capturing');
  }
}

// ========================= CAMERA FEED RENDERER (INTERACTIVE MULTI-TARGET) =========================
function renderCameraFeed(canvas, step, veh, forceBus) {
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const w = canvas.width, h = canvas.height;
  const isBus = forceBus !== undefined ? forceBus : step.mobile;

  // Background
  const grad = ctx.createLinearGradient(0, 0, 0, h);
  grad.addColorStop(0, '#0a0e17');
  grad.addColorStop(0.4, isBus ? '#1a1520' : '#141e2e');
  grad.addColorStop(1, isBus ? '#1a0f20' : '#1a1a2e');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, w, h);

  // Road
  ctx.fillStyle = '#2d2d3d';
  ctx.beginPath(); ctx.moveTo(0, h * 0.52); ctx.lineTo(w, h * 0.52); ctx.lineTo(w, h); ctx.lineTo(0, h); ctx.fill();
  
  // Lane Dividers
  ctx.strokeStyle = '#4a4a5a'; ctx.lineWidth = 1; ctx.setLineDash([12, 8]);
  ctx.beginPath(); ctx.moveTo(0, h * 0.68); ctx.lineTo(w, h * 0.68); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(0, h * 0.84); ctx.lineTo(w, h * 0.84); ctx.stroke();
  ctx.setLineDash([]);
  
  // Road Curb
  ctx.strokeStyle = isBus ? '#fbbf24' : '#00e5ff'; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(0, h * 0.52); ctx.lineTo(w, h * 0.52); ctx.stroke();

  // Recorded Mode Offset or Normal Sim Tick
  const isRecMode = STATE.liveCamera?.recordedMode;
  const timeProgress = isRecMode ? (STATE.liveCamera.recordedProgress || 0.7) : ((STATE.simTick % 60) / 60);

  // List of vehicles to render on the road for this frame
  const renderedList = [];

  // Vehicle 1: Active Target Vehicle
  if (veh) {
    const vx = isRecMode 
      ? (w * 0.15 + (timeProgress * w * 0.6))
      : (w * 0.3 + Math.sin(STATE.simTick * 0.3) * 14);
    const vy = h * 0.56;
    const vw = Math.min(74, w * 0.16);
    const vh = Math.min(42, h * 0.13);
    renderedList.push({
      id: veh.id,
      plate: veh.plate,
      type: veh.type,
      color: veh.color,
      make: veh.make,
      isTarget: true,
      conf: step.conf || 0.94,
      rect: { x: vx, y: vy, w: vw, h: vh }
    });
  }

  // Vehicle 2: Ambient / Passing Traffic (Opposite or Fast Lane)
  const amb1Plate = (veh && veh.plate === 'UP 16 AB 7843') ? 'DL 1C AE 4921' : 'UP 16 AB 7843';
  const amb1Type = (veh && veh.type === 'SUV') ? 'Sedan' : 'SUV';
  const amb1Color = (veh && veh.color === 'Black') ? 'White' : 'Black';
  const amb1Make = (amb1Type === 'SUV') ? 'Toyota Fortuner' : 'Maruti Swift Dzire';
  const amb1X = isRecMode
    ? (w * 0.75 - (timeProgress * w * 0.4))
    : (w * 0.65 + Math.cos(STATE.simTick * 0.25) * 18);
  const amb1Y = h * 0.70;
  const amb1W = Math.min(80, w * 0.17);
  const amb1H = Math.min(46, h * 0.14);
  renderedList.push({
    id: (amb1Plate === 'UP 16 AB 7843') ? 'VEH-002' : 'VEH-001',
    plate: amb1Plate,
    type: amb1Type,
    color: amb1Color,
    make: amb1Make,
    isTarget: false,
    conf: 0.88,
    rect: { x: amb1X, y: amb1Y, w: amb1W, h: amb1H }
  });

  // Vehicle 3: Ambient Traffic (Slow Lane / Red Hatchback or Auto)
  const amb2Plate = (veh && veh.plate === 'HR 26 DK 9912') ? 'DL 4C MH 2801' : 'HR 26 DK 9912';
  const amb2Type = 'Hatchback';
  const amb2Color = 'Red';
  const amb2Make = 'Hyundai i20';
  const amb2X = isRecMode
    ? (w * 0.05 + ((timeProgress * 1.3) % 1) * w * 0.8)
    : (w * 0.10 + Math.sin((STATE.simTick + 15) * 0.2) * 12);
  const amb2Y = h * 0.84;
  const amb2W = Math.min(68, w * 0.14);
  const amb2H = Math.min(38, h * 0.11);
  renderedList.push({
    id: (amb2Plate === 'HR 26 DK 9912') ? 'VEH-003' : 'VEH-AMB-3',
    plate: amb2Plate,
    type: amb2Type,
    color: amb2Color,
    make: amb2Make,
    isTarget: false,
    conf: 0.84,
    rect: { x: amb2X, y: amb2Y, w: amb2W, h: amb2H }
  });

  // Store for interactive click-to-track
  canvas._interactiveVehicles = renderedList;
  attachInteractiveCanvasListeners(canvas);

  // Render Vehicles
  renderedList.forEach(item => {
    const { x, y, w: vw, h: vh } = item.rect;
    const bodyColor = item.color === 'White' ? '#e2e8f0' :
                      item.color === 'Black' ? '#1e293b' :
                      item.color === 'Red' ? '#dc2626' :
                      item.color === 'Silver' ? '#94a3b8' :
                      item.color === 'Blue' ? '#2563eb' : '#fbbf24';

    // Shadow
    ctx.fillStyle = 'rgba(0,0,0,0.5)';
    ctx.fillRect(x + 2, y + vh - 2, vw - 4, 4);

    // Car Body
    ctx.fillStyle = bodyColor;
    ctx.beginPath();
    ctx.roundRect ? ctx.roundRect(x, y, vw, vh, 4) : ctx.rect(x, y, vw, vh);
    ctx.fill();
    ctx.strokeStyle = '#000';
    ctx.lineWidth = 1;
    ctx.stroke();

    // Windshield & Windows
    ctx.fillStyle = 'rgba(56, 189, 248, 0.35)';
    ctx.fillRect(x + vw * 0.68, y + 4, vw * 0.24, vh - 8);

    // Headlights
    ctx.fillStyle = '#fef08a';
    ctx.beginPath(); ctx.arc(x + vw - 2, y + 8, 3, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(x + vw - 2, y + vh - 8, 3, 0, Math.PI * 2); ctx.fill();

    // License Plate
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(x + 8, y + vh - 11, Math.min(48, vw * 0.65), 9);
    ctx.fillStyle = '#000000';
    ctx.font = `bold ${Math.max(6, Math.min(8, w * 0.012))}px JetBrains Mono, monospace`;
    ctx.fillText(item.plate, x + 10, y + vh - 4);

    // OCR Bounding Box
    ctx.strokeStyle = item.isTarget ? '#00e5ff' : 'rgba(255, 255, 255, 0.4)';
    ctx.lineWidth = item.isTarget ? 1.5 : 1;
    ctx.strokeRect(x + 6, y + vh - 13, Math.min(52, vw * 0.7), 13);

    // Vehicle Detection Bounding Box
    ctx.strokeStyle = item.isTarget ? '#69f0ae' : 'rgba(148, 163, 184, 0.6)';
    ctx.lineWidth = item.isTarget ? 1.5 : 1;
    ctx.setLineDash(item.isTarget ? [] : [4, 3]);
    ctx.strokeRect(x - 3, y - 3, vw + 6, vh + 6);
    ctx.setLineDash([]);

    // Detection Label Tag above vehicle
    ctx.fillStyle = item.isTarget ? 'rgba(105, 240, 174, 0.9)' : 'rgba(15, 23, 42, 0.85)';
    ctx.fillRect(x - 3, y - 16, Math.min(88, vw + 14), 13);
    ctx.fillStyle = item.isTarget ? '#000000' : '#38bdf8';
    ctx.font = `bold ${Math.max(7, Math.min(9, w * 0.013))}px Inter, sans-serif`;
    ctx.fillText(`${item.isTarget ? ' ' : ''}${item.type} ${(item.conf * 100).toFixed(0)}%`, x, y - 6);

    // Check if vehicle is hovered by mouse
    const isHovered = canvas._hoveredVehicle && canvas._hoveredVehicle.plate === item.plate;
    if (isHovered) {
      // Draw Tactical Lock Reticle
      ctx.strokeStyle = '#00e5ff';
      ctx.lineWidth = 2;
      const pad = 8;
      const rx = x - pad, ry = y - pad, rw = vw + pad * 2, rh = vh + pad * 2;
      const cl = 12;
      ctx.beginPath();
      ctx.moveTo(rx, ry + cl); ctx.lineTo(rx, ry); ctx.lineTo(rx + cl, ry);
      ctx.moveTo(rx + rw - cl, ry); ctx.lineTo(rx + rw, ry); ctx.lineTo(rx + rw, ry + cl);
      ctx.moveTo(rx, ry + rh - cl); ctx.lineTo(rx, ry + rh); ctx.lineTo(rx + cl, ry + rh);
      ctx.moveTo(rx + rw - cl, ry + rh); ctx.lineTo(rx + rw, ry + rh); ctx.lineTo(rx + rw, ry + rh - cl);
      ctx.stroke();

      // Lock Badge
      ctx.fillStyle = 'rgba(0, 229, 255, 0.95)';
      ctx.fillRect(rx, ry + rh + 3, rw, 15);
      ctx.fillStyle = '#000';
      ctx.font = 'bold 9px JetBrains Mono, monospace';
      ctx.fillText(' CLICK TO LOCK & TRACK', rx + 4, ry + rh + 14);
    }
  });

  // Top Camera HUD
  ctx.fillStyle = 'rgba(0,0,0,0.7)';
  ctx.fillRect(0, 0, w, 24);
  ctx.fillStyle = isRecMode ? '#fbbf24' : (isBus ? '#fbbf24' : '#00e5ff');
  ctx.font = `bold ${Math.max(8, Math.min(10, w * 0.016))}px JetBrains Mono, monospace`;
  ctx.fillText(`${isRecMode ? ' ARCHIVE PLAYBACK' : '* LIVE STREAM'}  ${step.cam}  ${isBus ? 'MOBILE NPU NODE' : 'FIXED ANPR'}`, 8, 15);

  // Timestamp
  const now = new Date();
  const ts = isRecMode 
    ? (STATE.liveCamera?.recordedTimestamp || '2026-09-19 10:24:18 IST')
    : `IST ${now.getHours().toString().padStart(2,'0')}:${now.getMinutes().toString().padStart(2,'0')}:${now.getSeconds().toString().padStart(2,'0')}  GPS: ${step.lat.toFixed(4)}, ${step.lng.toFixed(4)}`;
  ctx.fillStyle = isRecMode ? '#fbbf24' : '#94a3b8';
  ctx.font = `${Math.max(7, Math.min(8, w * 0.013))}px JetBrains Mono`;
  ctx.fillText(ts, 8, 22);

  // Click-to-Track Hint Prompt
  ctx.fillStyle = 'rgba(10, 14, 23, 0.75)';
  ctx.fillRect(6, h - 18, 205, 16);
  ctx.fillStyle = '#38bdf8';
  ctx.font = 'bold 8px Inter';
  ctx.fillText(' Click any vehicle to acquire & track', 10, h - 6);

  // Quality badge
  ctx.fillStyle = 'rgba(0,0,0,0.7)';
  ctx.fillRect(w - 110, h - 18, 110, 18);
  ctx.fillStyle = '#34d399';
  ctx.font = `bold ${Math.max(7, Math.min(8, w * 0.013))}px Inter`;
  ctx.fillText(`TRT 45 FPS · 99.2%`, w - 105, h - 6);

  // Night Vision effect
  if (STATE.nightVision || STATE.liveCamera?.nightVision) {
    ctx.fillStyle = 'rgba(0, 255, 120, 0.12)';
    ctx.fillRect(0, 0, w, h);
    ctx.fillStyle = '#00ff88';
    ctx.font = 'bold 8px JetBrains Mono';
    ctx.fillText(' IR THERMAL NIGHT-VISION +18dB', w - 190, 14);
  }

  // Scanlines
  ctx.strokeStyle = 'rgba(255,255,255,0.02)';
  ctx.lineWidth = 1;
  for (let y = 0; y < h; y += 3) { ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(w, y); ctx.stroke(); }
}

// ========================= SURVEILLANCE DUAL FEEDS =========================
function renderSurveillanceFeeds(step, veh) {
  const fixedCanvas = document.getElementById('surv-canvas-fixed');
  const busCanvas = document.getElementById('surv-canvas-bus');

  // Find the fixed step and bus step closest to current
  let fixedStep = step.mobile ? (veh.trajectory.find(s => !s.mobile) || step) : step;
  let busStep = step.mobile ? step : (veh.trajectory.find(s => s.mobile) || step);

  renderCameraFeed(fixedCanvas, fixedStep, veh, false);
  renderCameraFeed(busCanvas, busStep, veh, true);

  // Update fixed cam info
  const fCamId = document.getElementById('surv-fixed-cam-id');
  if (fCamId) fCamId.textContent = fixedStep.cam;
  const fMeta = document.getElementById('surv-fixed-meta');
  if (fMeta) fMeta.textContent = `${getCameraName(fixedStep.cam)} · DeepStream TRT INT8 · 45 FPS`;
  const fConf = document.getElementById('surv-fixed-conf');
  if (fConf) fConf.textContent = `${(fixedStep.conf * 100).toFixed(0)}%`;
  const fTs = document.getElementById('surv-fixed-timestamp');
  if (fTs) { const now = new Date(); fTs.textContent = `${now.getHours().toString().padStart(2,'0')}:${now.getMinutes().toString().padStart(2,'0')}:${now.getSeconds().toString().padStart(2,'0')}.${now.getMilliseconds().toString().padStart(3,'0')}`; }
  const fGps = document.getElementById('surv-fixed-gps');
  if (fGps) fGps.textContent = `GPS: ${fixedStep.lat.toFixed(4)}, ${fixedStep.lng.toFixed(4)}`;

  // Update bus cam info
  const bCamId = document.getElementById('surv-bus-cam-id');
  if (bCamId) bCamId.textContent = busStep.cam;
  const bMeta = document.getElementById('surv-bus-meta');
  if (bMeta) bMeta.textContent = `${getCameraName(busStep.cam)} · Hailo-8 NPU · STN Active`;
  const bConf = document.getElementById('surv-bus-conf');
  if (bConf) bConf.textContent = `${(busStep.conf * 100).toFixed(0)}%`;
  const bTs = document.getElementById('surv-bus-timestamp');
  if (bTs) { const now = new Date(); bTs.textContent = `${now.getHours().toString().padStart(2,'0')}:${now.getMinutes().toString().padStart(2,'0')}:${now.getSeconds().toString().padStart(2,'0')}.${now.getMilliseconds().toString().padStart(3,'0')}`; }
  const bGps = document.getElementById('surv-bus-gps');
  if (bGps) bGps.textContent = `GPS: ${busStep.lat.toFixed(4)}, ${busStep.lng.toFixed(4)}`;

  // Speed + distance
  const survSpeed = document.getElementById('surv-speed');
  if (survSpeed) survSpeed.textContent = `${(35 + Math.random() * 15).toFixed(0)} km/h`;
  const survDist = document.getElementById('surv-distance');
  if (survDist) { const d = haversine(fixedStep.lat, fixedStep.lng, busStep.lat, busStep.lng); survDist.textContent = `${d.toFixed(1)} km`; }
}

// ========================= HUD UPDATES =========================
function updateGISHud(stepIndex, veh) {
  const prevStep = stepIndex > 0 ? veh.trajectory[stepIndex - 1] : null;
  const currStep = veh.trajectory[stepIndex];
  const nextStep = stepIndex < veh.trajectory.length - 1 ? veh.trajectory[stepIndex + 1] : null;

  setHudElements('gis-hud-prev', 'gis-hud-curr', 'gis-hud-next', 'gis-hud-gap', 'gis-cone-val', 'gis-proto-val', prevStep, currStep, nextStep);
}

function updateSurvHud(stepIndex, veh) {
  const prevStep = stepIndex > 0 ? veh.trajectory[stepIndex - 1] : null;
  const currStep = veh.trajectory[stepIndex];
  const nextStep = stepIndex < veh.trajectory.length - 1 ? veh.trajectory[stepIndex + 1] : null;

  setHudElements('surv-hud-prev', 'surv-hud-curr', 'surv-hud-next', 'surv-hud-gap', 'surv-cone', 'surv-proto', prevStep, currStep, nextStep);
}

function setHudElements(prevId, currId, nextId, gapId, coneId, protoId, prevStep, currStep, nextStep) {
  const prevEl = document.getElementById(prevId);
  const currEl = document.getElementById(currId);
  const nextEl = document.getElementById(nextId);
  const gapEl = document.getElementById(gapId);
  const coneEl = document.getElementById(coneId);
  const protoEl = document.getElementById(protoId);

  if (prevEl) prevEl.textContent = prevStep ? prevStep.cam : 'ORIGIN';
  if (currEl) {
    currEl.textContent = `${currStep.cam} ${currStep.mobile ? '(MOBILE)' : '(FIXED)'}`;
    currEl.style.background = currStep.mobile ? 'var(--accent-yellow)' : 'var(--accent-cyan)';
    currEl.style.color = '#000';
  }
  if (nextEl) nextEl.textContent = nextStep ? nextStep.cam : 'EXIT';
  if (gapEl) {
    if (currStep.mobile) {
      gapEl.innerHTML = `<span class="pulse-dot-amber"></span> ${currStep.street || 'BLIND ZONE BRIDGED: Bus Mobile'}`;
      gapEl.style.color = 'var(--accent-yellow)';
    } else if (prevStep && prevStep.mobile) {
      gapEl.innerHTML = `[OK] ${currStep.street || 'RE-EMERGED AT JUNCTION'}`;
      gapEl.style.color = 'var(--accent-green)';
    } else {
      gapEl.innerHTML = ` ${currStep.street || 'OFFICIAL CORRIDOR'}`;
      gapEl.style.color = 'var(--accent-cyan)';
    }
  }
  if (coneEl) {
    let dist = 2.4;
    if (prevStep) dist = haversine(prevStep.lat, prevStep.lng, currStep.lat, currStep.lng);
    coneEl.textContent = `r = ${(Math.max(dist * 1.3, 2.0)).toFixed(1)} km | dt = ${currStep.time} min`;
  }
  if (protoEl) protoEl.textContent = currStep.mobile ? 'AIS-140 Relay · 180B MQTT' : 'Fixed CCTV · DeepStream';
}

// ========================= NEARBY ANPR MATRIX =========================
function updateNearbyANPR(step, veh) {
  // GIS window
  const gisCurrName = document.getElementById('gis-anpr-curr');
  if (gisCurrName) gisCurrName.textContent = `${step.cam} — ${getCameraName(step.cam)}`;
  const gisCurrMeta = document.getElementById('gis-anpr-meta');
  if (gisCurrMeta) gisCurrMeta.textContent = step.mobile ? 'Mobile · Hailo-8 NPU · STN · MQTT' : 'Fixed · DeepStream TRT · 45 FPS';

  // Nearby fixed
  updateNearbyList('gis-nearby-fixed', step, FIXED_CAMERAS, 3);
  updateNearbyList('gis-nearby-mobile', step, BUS_ROUTES, 2, true);
  updateNearbyList('grid-nearby', step, FIXED_CAMERAS, 2);

  // Grid current node
  const gridCurr = document.getElementById('grid-curr-node');
  if (gridCurr) gridCurr.textContent = `${step.cam} — ${getCameraName(step.cam)}`;

  // Next intercept
  const interceptEl = document.getElementById('gis-next-intercept');
  if (interceptEl) {
    const stepIdx = veh.trajectory.indexOf(step);
    if (stepIdx >= 0 && stepIdx < veh.trajectory.length - 1) {
      const nextStep = veh.trajectory[stepIdx + 1];
      interceptEl.textContent = `${nextStep.cam} (${getCameraName(nextStep.cam)}) · ETA ~${Math.max(1, nextStep.time - step.time)}m`;
    } else {
      interceptEl.textContent = 'Route Completed';
    }
  }
}

function updateNearbyList(containerId, step, items, limit, isBus) {
  const el = document.getElementById(containerId);
  if (!el) return;
  el.innerHTML = '';
  const sorted = items
    .filter(c => (isBus ? c.id : c.id) !== step.cam)
    .map(c => {
      const pos = isBus ? (STATE.busPositions[c.id] || c.waypoints[0]) : c;
      return { ...c, dist: haversine(step.lat, step.lng, pos.lat, pos.lng) };
    })
    .sort((a, b) => a.dist - b.dist)
    .slice(0, limit);

  sorted.forEach(c => {
    const row = document.createElement('div');
    row.className = 'nearby-row';
    row.innerHTML = `<span class="nr-name">${c.id}</span><span class="nr-dist">${c.dist.toFixed(1)} km</span><span class="nr-badge ${isBus ? 'mobile' : 'fixed'}">${isBus ? 'PARALLEL' : 'ONLINE'}</span>`;
    el.appendChild(row);
  });
}

// ========================= CONFIDENCE =========================
function computeConfidence(prevStep, currStep, veh) {
  const plateSim = currStep.conf * (0.85 + Math.random() * 0.15);
  const timeDelta = (currStep.time - prevStep.time) * 60;
  const dist = haversine(prevStep.lat, prevStep.lng, currStep.lat, currStep.lng);
  const expectedTime = (dist / 35) * 3600;
  const timeScore = Math.exp(-Math.pow(timeDelta - expectedTime, 2) / (2 * Math.pow(120, 2)));
  const timeFeas = Math.min(1, Math.max(0, 0.6 + timeScore * 0.4));
  const roadFit = 0.7 + Math.random() * 0.28;
  const quality = currStep.mobile ? (0.65 + Math.random() * 0.25) : (0.85 + Math.random() * 0.15);
  const overall = 0.40 * plateSim + 0.25 * timeFeas + 0.20 * roadFit + 0.15 * quality;
  let tier = overall >= 0.80 ? 'HIGH' : overall >= 0.55 ? 'MEDIUM' : 'LOW';
  return { overall, plate: plateSim, time: timeFeas, road: roadFit, quality, tier };
}

function updateConfidence(conf) {
  // GIS confidence
  updateConfRing('gis-conf-ring', 'gis-conf-val', 'gis-conf-tier', conf);
  updateConfFactors('gis-conf-plate', 'gis-conf-plate-val', 'gis-conf-time', 'gis-conf-time-val', 'gis-conf-road', 'gis-conf-road-val', 'gis-conf-quality', 'gis-conf-quality-val', conf);

  // Grid confidence
  updateConfRing('grid-conf-ring', 'grid-conf-val', 'grid-conf-tier', conf);
}

function updateConfRing(ringId, valId, tierId, conf) {
  const ring = document.getElementById(ringId);
  const valEl = document.getElementById(valId);
  const tierEl = document.getElementById(tierId);
  if (!ring || !valEl || !tierEl) return;

  if (!conf) {
    ring.style.strokeDashoffset = 263.89;
    valEl.textContent = '—';
    tierEl.textContent = 'AWAITING'; tierEl.className = 'conf-tier';
    return;
  }
  ring.style.strokeDashoffset = 263.89 * (1 - conf.overall);
  ring.style.stroke = conf.tier === 'HIGH' ? '#34d399' : conf.tier === 'MEDIUM' ? '#fbbf24' : '#f87171';
  valEl.textContent = (conf.overall * 100).toFixed(0) + '%';
  tierEl.textContent = conf.tier;
  tierEl.className = `conf-tier ${conf.tier.toLowerCase()}`;
}

function updateConfFactors(plateId, plateValId, timeId, timeValId, roadId, roadValId, qualId, qualValId, conf) {
  if (!conf) return;
  const ids = [[plateId, plateValId, conf.plate], [timeId, timeValId, conf.time], [roadId, roadValId, conf.road], [qualId, qualValId, conf.quality]];
  ids.forEach(([barId, valId, val]) => {
    const bar = document.getElementById(barId);
    const v = document.getElementById(valId);
    if (bar) bar.style.width = (val * 100) + '%';
    if (v) v.textContent = (val * 100).toFixed(0) + '%';
  });
}

// ========================= TELEMETRY =========================
function addTelemetryEntry(step, veh) {
  const feeds = ['gis-telemetry-feed', 'grid-telemetry-feed'];
  const now = new Date();
  const ts = `${now.getHours().toString().padStart(2,'0')}:${now.getMinutes().toString().padStart(2,'0')}:${now.getSeconds().toString().padStart(2,'0')}`;

  feeds.forEach(feedId => {
    const feed = document.getElementById(feedId);
    if (!feed) return;
    const item = document.createElement('div');
    item.className = `telem-item ${step.mobile ? 'mobile' : 'detection'}`;
    item.innerHTML = `<span class="telem-ts">[${ts}]</span> <span class="telem-node">${step.cam}</span> - <span class="telem-plate">${veh.plate}</span> | ${(step.conf * 100).toFixed(0)}% ${step.mobile ? '| <span style="color:#fbbf24">MOBILE</span>' : ''} ${veh.isStolen ? '| <span class="telem-alert-text"> HOTLIST</span>' : ''}`;
    feed.insertBefore(item, feed.firstChild);
    while (feed.children.length > CONFIG.MAX_TELEMETRY) feed.removeChild(feed.lastChild);
  });

  STATE.totalDetections++;
  document.getElementById('stat-detections').textContent = STATE.totalDetections;
}

// ========================= ANOMALY FEED =========================
function addAnomaly(type, severity, description) {
  const feed = document.getElementById('gis-anomaly-feed');
  if (!feed) return;
  const now = new Date();
  const ts = `${now.getHours().toString().padStart(2,'0')}:${now.getMinutes().toString().padStart(2,'0')}:${now.getSeconds().toString().padStart(2,'0')}`;
  const item = document.createElement('div');
  item.className = `anomaly-item ${severity}`;
  item.innerHTML = `<div class="anomaly-header"><span class="anomaly-type">${type}</span><span class="anomaly-time">${ts}</span></div><div class="anomaly-desc">${description}</div>`;
  feed.insertBefore(item, feed.firstChild);
  while (feed.children.length > CONFIG.MAX_ANOMALIES) feed.removeChild(feed.lastChild);
  STATE.totalAlerts++;
  document.getElementById('stat-alerts').textContent = STATE.totalAlerts;
}

// ========================= SIMULATION ENGINE =========================
function clearAllSimulationTimers() {
  if (STATE.timers) {
    if (STATE.timers.trajectory) clearInterval(STATE.timers.trajectory);
    if (STATE.timers.bus) clearInterval(STATE.timers.bus);
    if (STATE.timers.vehicleGlide) clearInterval(STATE.timers.vehicleGlide);
    if (STATE.timers.telem) clearInterval(STATE.timers.telem);
    if (STATE.timers.anomaly) clearInterval(STATE.timers.anomaly);
    if (STATE.timers.hotlist) clearInterval(STATE.timers.hotlist);
  }
  STATE.timers = { trajectory: null, bus: null, vehicleGlide: null, telem: null, anomaly: null, hotlist: null };
}

function startSimulation() {
  clearAllSimulationTimers();

  // Initial anomalies
  setTimeout(() => addAnomaly('IMPOSSIBLE SPEED', 'critical', 'DL 8C BZ 1122 — CP <-> Nehru Place in 1min. 720 km/h. Cloned plate.'), 2000);
  setTimeout(() => addAnomaly('IDENTITY CONFLICT', 'critical', 'UP 16 AB 7843 — Simultaneous at AIIMS & Lajpat. Duplicate plate.'), 4000);
  setTimeout(() => addAnomaly('SENSOR DEGRADATION', 'warning', 'CAM-JNC-12 — Laplacian blur 42. Lens obscured.'), 6000);

  // Start continuous, building-free road glide along official arterial corridors
  startVehicleRoadGlide();

  // Move buses
  STATE.timers.bus = setInterval(moveBuses, CONFIG.SIM_SPEED);

  // Coverage
  const covEl = document.getElementById('gis-coverage');
  if (covEl) covEl.textContent = ((FIXED_CAMERAS.length * 0.8 + BUS_ROUTES.length * 2.2) / (FIXED_CAMERAS.length + BUS_ROUTES.length) * 35).toFixed(0) + '%';

  // Random telemetry
  STATE.timers.telem = setInterval(() => {
    const cam = FIXED_CAMERAS[Math.floor(Math.random() * FIXED_CAMERAS.length)];
    const plates = ['DL 4C AB 3321', 'HR 38 AQ 9102', 'UP 80 BD 6644', 'RJ 27 CA 1188'];
    const plate = plates[Math.floor(Math.random() * plates.length)];
    const conf = (85 + Math.random() * 14).toFixed(0);
    const feeds = ['gis-telemetry-feed', 'grid-telemetry-feed'];
    const now = new Date();
    const ts = `${now.getHours().toString().padStart(2,'0')}:${now.getMinutes().toString().padStart(2,'0')}:${now.getSeconds().toString().padStart(2,'0')}`;
    feeds.forEach(feedId => {
      const feed = document.getElementById(feedId);
      if (!feed) return;
      const item = document.createElement('div');
      item.className = 'telem-item detection';
      item.innerHTML = `<span class="telem-ts">[${ts}]</span> <span class="telem-node">${cam.id}</span> - <span class="telem-plate">${plate}</span> | ${conf}%`;
      feed.insertBefore(item, feed.firstChild);
      while (feed.children.length > CONFIG.MAX_TELEMETRY) feed.removeChild(feed.lastChild);
    });
    STATE.totalDetections++;
    const statDetections = document.getElementById('stat-detections');
    if (statDetections) statDetections.textContent = STATE.totalDetections;

    // Stream live microservice API call to terminal
    if (STATE.totalDetections % 3 === 0) {
      const isMqtt = Math.random() > 0.5;
      const apiType = isMqtt ? 'mqtt' : 'deepstream';
      const def = API_ENDPOINTS[apiType];
      if (def) {
        const measuredLat = (Math.random() * 6 + 12).toFixed(1);
        logApiCallToTerminal({
          time: `${ts}.${String(now.getMilliseconds()).padStart(3, '0')}`,
          name: def.name,
          method: def.method,
          url: def.url,
          status: 200,
          latency: measuredLat,
          extra: isMqtt ? `BUS-DTC-${Math.random() > 0.5 ? '419' : '522'} · 180B` : `${cam.id} · ${plate}`,
          payload: { plate, conf, node: cam.id, ts: now.toISOString() }
        });
      }
    }
  }, CONFIG.TELEMETRY_INTERVAL);

  // Periodic anomalies
  STATE.timers.anomaly = setInterval(() => {
    const anomalies = [
      ['ROUTE DEVIATION', 'warning', 'HR 26 DK 9912 — Diverged from Ring Road towards Vasant Kunj.'],
      ['SENSOR DEGRADATION', 'warning', `CAM-JNC-${String(Math.floor(Math.random() * 12) + 1).padStart(2, '0')} — Frame quality dropped. Laplacian: ${(30 + Math.random() * 60).toFixed(0)}`],
      ['IMPOSSIBLE SPEED', 'critical', 'MH 12 FG 3391 — 8km in 45s. 640 km/h. CLONED PLATE.'],
    ];
    const a = anomalies[Math.floor(Math.random() * anomalies.length)];
    addAnomaly(a[0], a[1], a[2]);
  }, 12000);

  // Hotlist latency
  STATE.timers.hotlist = setInterval(() => {
    const el = document.getElementById('hotlist-latency');
    if (el) el.textContent = (2.5 + Math.random() * 4.5).toFixed(1) + 'ms';
  }, 3000);
}

function moveBuses() {
  if (!STATE.busScannerCones) STATE.busScannerCones = {};

  BUS_ROUTES.forEach(bus => {
    let idx = STATE.busWaypointIndex[bus.id];
    const wps = bus.waypoints;
    if (idx >= wps.length - 1) { STATE.busWaypointIndex[bus.id] = 0; idx = 0; }
    const from = wps[idx], to = wps[idx + 1];
    if (!to) return;
    const t = (STATE.simTick % 5) / 5;
    const lat = from.lat + (to.lat - from.lat) * t;
    const lng = from.lng + (to.lng - from.lng) * t;
    STATE.busPositions[bus.id] = { lat, lng };

    const marker = STATE.markers.buses[bus.id];
    if (marker) marker.setLatLng([lat, lng]);

    // Render / update mobile ANPR scanner cone ahead of the bus on Tactical GIS Map
    if (STATE.maps.gis) {
      const dLng = to.lng - from.lng;
      const dLat = to.lat - from.lat;
      const heading = (Math.atan2(dLng, dLat) * 180 / Math.PI + 360) % 360;

      // Small 50m forward scanner circle representing Hailo-8 NPU camera FOV
      const fovDist = 0.0006;
      const rad = heading * Math.PI / 180;
      const fovLat = lat + Math.cos(rad) * fovDist;
      const fovLng = lng + Math.sin(rad) * fovDist;

      if (!STATE.busScannerCones[bus.id]) {
        STATE.busScannerCones[bus.id] = L.circle([fovLat, fovLng], {
          radius: 65,
          color: '#fbbf24',
          fillColor: '#fbbf24',
          fillOpacity: 0.12,
          weight: 1,
          dashArray: '4 4'
        }).addTo(STATE.maps.gis);
        STATE.busScannerCones[bus.id].bindTooltip(` ${bus.id} Mobile ANPR Scanning Zone`, { sticky: true });
      } else {
        STATE.busScannerCones[bus.id].setLatLng([fovLat, fovLng]);
      }
    }

    if (t >= 0.99) STATE.busWaypointIndex[bus.id] = idx + 1;
  });
  STATE.simTick++;
}

// ========================= GIS TIMELINE CONTROLS =========================
function initGISTimelineControls() {
  const btnPrev = document.getElementById('btn-gis-prev');
  const btnNext = document.getElementById('btn-gis-next');
  const btnPlay = document.getElementById('btn-gis-play');
  const btnPause = document.getElementById('btn-gis-pause');

  if (btnPrev) btnPrev.onclick = () => {
    const veh = VEHICLES.find(v => v.id === STATE.selectedVehicle);
    if (!veh) return;
    const curr = STATE.currentTrajectoryStep[veh.id] || 0;
    activateTimelineStep(veh, curr > 0 ? curr - 1 : veh.trajectory.length - 1);
  };
  if (btnNext) btnNext.onclick = () => {
    const veh = VEHICLES.find(v => v.id === STATE.selectedVehicle);
    if (!veh) return;
    const curr = STATE.currentTrajectoryStep[veh.id] || 0;
    activateTimelineStep(veh, (curr + 1) % veh.trajectory.length);
  };
  if (btnPlay) btnPlay.onclick = () => {
    STATE.isSimPaused = false;
    if (btnPause) btnPause.textContent = ' Pause Sim';
  };
  if (btnPause) btnPause.onclick = () => {
    STATE.isSimPaused = !STATE.isSimPaused;
    btnPause.textContent = STATE.isSimPaused ? ' Resume' : ' Pause Sim';
    btnPause.classList.toggle('active', !STATE.isSimPaused);
  };
}

// ========================= DOSSIER (WINDOW 4) =========================
function renderDossier() {
  const veh = VEHICLES.find(v => v.id === STATE.selectedVehicle) || VEHICLES[0];
  const sub = document.getElementById('dossier-subtitle');
  if (sub) sub.textContent = `Target: ${veh.plate} · ${veh.make} (${veh.color} ${veh.type})`;
  const plate = document.getElementById('dossier-plate');
  if (plate) plate.textContent = veh.plate;
  const reid = document.getElementById('dossier-reid');
  if (reid) reid.textContent = veh.reidHash;
  const count = document.getElementById('dossier-count');
  if (count) count.textContent = `${veh.trajectory.length} Sightings`;
  const bridged = document.getElementById('dossier-bridged');
  if (bridged) bridged.textContent = `${veh.trajectory.filter(t => t.mobile).length} Mobile`;

  const gallery = document.getElementById('dossier-gallery');
  if (!gallery) return;
  gallery.innerHTML = '';

  veh.trajectory.forEach((step, idx) => {
    const card = document.createElement('div');
    card.className = `shot-card ${step.mobile ? 'mobile-node' : 'fixed-node'}`;
    const canvasId = `dossier-shot-${idx}`;
    const hash = generateHash(veh.plate + step.cam + step.time);
    card.innerHTML = `
      <div class="shot-preview-container">
        <canvas class="shot-preview-canvas" id="${canvasId}" width="280" height="140"></canvas>
        <div class="shot-top-tag">${step.cam} · ${step.mobile ? 'MOBILE BUS' : 'FIXED ANPR'}</div>
        <div class="shot-step-num">SHOT #${idx + 1}</div>
      </div>
      <div class="shot-body">
        <div class="shot-plate-crop-row">
          <div class="spc-left"><span class="spc-crop-box">${veh.plate}</span>${step.mobile ? '<span style="font-size:8px;color:#fbbf24;font-weight:700">STN</span>' : ''}</div>
          <span class="spc-conf-badge">${(step.conf * 100).toFixed(0)}% OCR</span>
        </div>
        <div class="shot-info-table">
          <div class="sit-row"><span class="sit-lbl">Camera:</span><span class="sit-val">${getCameraName(step.cam)}</span></div>
          <div class="sit-row"><span class="sit-lbl">Time:</span><span class="sit-val">T + ${step.time}m</span></div>
          <div class="sit-row"><span class="sit-lbl">GPS:</span><span class="sit-val">${step.lat.toFixed(4)}, ${step.lng.toFixed(4)}</span></div>
          <div class="sit-row"><span class="sit-lbl">Edge:</span><span class="sit-val">${step.mobile ? 'Hailo-8 NPU' : 'DeepStream TRT'}</span></div>
          <div class="sit-row"><span class="sit-lbl">Re-ID:</span><span class="sit-val">${veh.reidHash}</span></div>
        </div>
        <div class="shot-hash-line">SHA-256: ${hash}</div>
        <button class="assc-btn primary" style="font-size:9.5px;padding:5px 8px;width:100%;margin-top:8px;" onclick="inspectSightingFromDossier(${idx})">
          📍 View &amp; Inspect Sighting on Tactical Map
        </button>
      </div>
    `;
    gallery.appendChild(card);
    setTimeout(() => drawShotCanvas(canvasId, step, veh), 30);
  });

  // Export button
  const btnExport = document.getElementById('btn-export-dossier2');
  if (btnExport) btnExport.onclick = () => {
    alert(`[LEGAL DOSSIER GENERATED]\n\nTarget: ${veh.plate}\nRe-ID: ${veh.reidHash}\nSightings: ${veh.trajectory.length}\nLegal: BSA Sec 63 / IEA Sec 65B\nSeal: SHA-256 Verified`);
  };
}

function inspectSightingFromDossier(idx) {
  const veh = VEHICLES.find(v => v.id === STATE.selectedVehicle) || VEHICLES[0];
  switchWindow('gis');
  activateTimelineStep(veh, idx);
  if (STATE.maps.gis && veh.trajectory && veh.trajectory[idx]) {
    const step = veh.trajectory[idx];
    STATE.maps.gis.flyTo([step.lat, step.lng], 15, { animate: true, duration: 1.0 });
  }
  playSound('chirp');
  showToast('🗺️ SIGHTING LOCATED ON MAP', `Focused on Sighting #${idx + 1} (${veh.trajectory[idx]?.cam})`);
}

function drawShotCanvas(canvasId, step, veh) {
  const canvas = document.getElementById(canvasId);
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const w = canvas.width, h = canvas.height;

  const grad = ctx.createLinearGradient(0, 0, 0, h);
  grad.addColorStop(0, '#0d1117'); grad.addColorStop(0.5, '#162032'); grad.addColorStop(1, '#1b1b2f');
  ctx.fillStyle = grad; ctx.fillRect(0, 0, w, h);

  ctx.fillStyle = '#262638';
  ctx.beginPath(); ctx.moveTo(0, h*0.55); ctx.lineTo(w, h*0.55); ctx.lineTo(w, h); ctx.lineTo(0, h); ctx.fill();

  ctx.strokeStyle = '#f59e0b'; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(0, h*0.55); ctx.lineTo(w, h*0.55); ctx.stroke();

  const vx = w * 0.32, vy = h * 0.58, vw = 65, vh = 35;
  const bodyColor = veh.color === 'White' ? '#d4d4d8' : veh.color === 'Black' ? '#27272a' : veh.color === 'Red' ? '#dc2626' : '#6b7280';
  ctx.fillStyle = bodyColor; ctx.fillRect(vx, vy, vw, vh);
  ctx.fillStyle = 'rgba(56,189,248,0.25)'; ctx.fillRect(vx + 42, vy + 3, 16, vh - 10);
  ctx.fillStyle = '#f8fafc'; ctx.fillRect(vx + 8, vy + vh - 10, 38, 8);
  ctx.fillStyle = '#000'; ctx.font = '5px JetBrains Mono'; ctx.fillText(veh.plate, vx + 10, vy + vh - 4);
  ctx.strokeStyle = step.mobile ? '#fbbf24' : '#00e5ff'; ctx.lineWidth = 1.5; ctx.strokeRect(vx - 2, vy - 2, vw + 4, vh + 4);
  ctx.fillStyle = step.mobile ? 'rgba(251,191,36,0.9)' : 'rgba(0,229,255,0.9)';
  ctx.fillRect(vx - 2, vy - 13, 55, 11);
  ctx.fillStyle = '#000'; ctx.font = 'bold 7px Inter'; ctx.fillText(`${veh.type} ${(step.conf * 100).toFixed(0)}%`, vx, vy - 4);
}

// ========================= PS 124 SIMULATION (WINDOW 5) =========================
let ps124Interval = null;

function startPS124Simulation() {
  if (ps124Interval) return; // Already running

  ps124Interval = setInterval(() => {
    // Run if PS124 tab is active OR if we're in 50:25:25 split mode (PS124 is always visible)
    if (STATE.activeWindow !== 'ps124' && !document.body.classList.contains('mode-split5025')) return;

    // Helper for dual text updates
    const updateText = (baseId, val) => {
      [baseId, baseId + '-pane'].forEach(id => {
        const el = document.getElementById(id);
        if (el) el.textContent = val;
      });
    };

    // Accelerometer / Pothole
    const accel = 0.5 + Math.random() * 2.0 + (Math.random() > 0.92 ? 3.0 : 0);
    STATE.ps124.accelHistory.push(accel);
    if (STATE.ps124.accelHistory.length > 60) STATE.ps124.accelHistory.shift();

    if (accel > 2.5) {
      STATE.ps124.potholeCount++;
      updateText('ps124-potholes', STATE.ps124.potholeCount);
      addPS124Log('ps124-pothole-log', ` POTHOLE DETECTED · IMU spike: ${accel.toFixed(1)}g · GPS: ${(28.6 + Math.random()*0.05).toFixed(4)}, ${(77.19 + Math.random()*0.05).toFixed(4)}`, '');
    }
    updateText('ps124-accel-peak', `${accel.toFixed(1)}g`);
    updateText('ps124-iri', (2.5 + Math.random() * 3.5).toFixed(1));
    drawAccelChart();

    // BRTS Violations
    if (Math.random() > 0.95) {
      STATE.ps124.violationCount++;
      STATE.ps124.challanCount++;
      STATE.ps124.fineTotal += 500;
      updateText('ps124-violations', STATE.ps124.violationCount);
      updateText('ps124-challans', STATE.ps124.challanCount);
      updateText('ps124-fine-total', `Rs ${STATE.ps124.fineTotal.toLocaleString()}`);
      const fakePlates = ['DL 3C AX 2244', 'HR 06 BD 9911', 'UP 32 EK 3377'];
      addPS124Log('ps124-brts-log', ` VIOLATION · ${fakePlates[Math.floor(Math.random()*fakePlates.length)]} in BRTS lane · E-Challan #${1000 + STATE.ps124.challanCount}`, 'violation');
    }
    drawBRTSCanvas();

    // Air Quality
    const pm25 = 40 + Math.random() * 80;
    const pm10 = 60 + Math.random() * 120;
    STATE.ps124.pm25History.push(pm25);
    STATE.ps124.pm10History.push(pm10);
    if (STATE.ps124.pm25History.length > 60) STATE.ps124.pm25History.shift();
    if (STATE.ps124.pm10History.length > 60) STATE.ps124.pm10History.shift();

    updateText('ps124-pm25', pm25.toFixed(0));
    updateText('ps124-pm10', pm10.toFixed(0));
    const aqiLevel = pm25 < 50 ? 'Good' : pm25 < 100 ? 'Moderate' : pm25 < 150 ? 'Unhealthy' : 'Hazardous';
    updateText('ps124-aqi-level', aqiLevel);
    drawAQIChart();

    if (Math.random() > 0.93) {
      addPS124Log('ps124-aqi-log', ` AQI Update · PM2.5: ${pm25.toFixed(0)} · PM10: ${pm10.toFixed(0)} · ${aqiLevel}`, 'aqi');
    }
  }, 800);
}

function addPS124Log(containerId, text, type) {
  const ids = [containerId, containerId + '-pane'];
  const now = new Date();
  const ts = `${now.getHours().toString().padStart(2,'0')}:${now.getMinutes().toString().padStart(2,'0')}:${now.getSeconds().toString().padStart(2,'0')}`;

  ids.forEach(id => {
    const log = document.getElementById(id);
    if (!log) return;
    const item = document.createElement('div');
    item.className = `psm-log-item ${type}`;
    item.innerHTML = `<span style="color:#00e5ff">[${ts}]</span> ${text}`;
    log.insertBefore(item, log.firstChild);
    while (log.children.length > 8) log.removeChild(log.lastChild);
  });
}

function drawAccelChart(targetId) {
  const canvasIds = targetId ? [targetId] : ['ps124-accel-chart', 'ps124-accel-chart-pane'];
  canvasIds.forEach(id => {
    const canvas = document.getElementById(id);
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    const w = canvas.width, h = canvas.height;
    ctx.clearRect(0, 0, w, h);

    // Background
    ctx.fillStyle = 'rgba(10,14,23,0.9)'; ctx.fillRect(0, 0, w, h);

    // Threshold line at 2.5g
    const threshY = h - (2.5 / 6) * h;
    ctx.strokeStyle = 'rgba(248,113,113,0.5)'; ctx.lineWidth = 1; ctx.setLineDash([4,4]);
    ctx.beginPath(); ctx.moveTo(0, threshY); ctx.lineTo(w, threshY); ctx.stroke(); ctx.setLineDash([]);
    ctx.fillStyle = 'rgba(248,113,113,0.7)'; ctx.font = '8px Inter'; ctx.fillText('2.5g THRESHOLD', w - 80, threshY - 3);

    // Draw data
    const data = STATE.ps124.accelHistory;
    if (data.length < 2) return;
    ctx.strokeStyle = '#00e5ff'; ctx.lineWidth = 1.5;
    ctx.beginPath();
    data.forEach((val, i) => {
      const x = (i / (data.length - 1)) * w;
      const y = h - (val / 6) * h;
      if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
    });
    ctx.stroke();

    // Highlight spikes
    data.forEach((val, i) => {
      if (val > 2.5) {
        const x = (i / (data.length - 1)) * w;
        const y = h - (val / 6) * h;
        ctx.fillStyle = '#f87171';
        ctx.beginPath(); ctx.arc(x, y, 3, 0, Math.PI * 2); ctx.fill();
      }
    });
  });
}

function drawBRTSCanvas(targetId) {
  const canvasIds = targetId ? [targetId] : ['ps124-brts-canvas', 'ps124-brts-canvas-pane'];
  canvasIds.forEach(id => {
    const canvas = document.getElementById(id);
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    const w = canvas.width, h = canvas.height;

    // Road scene
    ctx.fillStyle = '#0d1117'; ctx.fillRect(0, 0, w, h);
    ctx.fillStyle = '#2d2d3d';
    ctx.beginPath(); ctx.moveTo(0, h*0.4); ctx.lineTo(w, h*0.4); ctx.lineTo(w, h); ctx.lineTo(0, h); ctx.fill();

    // BRTS dedicated lane (red stripe)
    ctx.fillStyle = 'rgba(248,113,113,0.15)';
    ctx.fillRect(0, h*0.4, w, h*0.25);
    ctx.strokeStyle = '#f87171'; ctx.lineWidth = 2; ctx.setLineDash([8,4]);
    ctx.beginPath(); ctx.moveTo(0, h*0.4); ctx.lineTo(w, h*0.4); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(0, h*0.65); ctx.lineTo(w, h*0.65); ctx.stroke();
    ctx.setLineDash([]);

    // Label
    ctx.fillStyle = 'rgba(248,113,113,0.6)'; ctx.font = 'bold 10px Inter'; ctx.fillText('DEDICATED BRTS LANE', 10, h*0.55);

    // Bus icon
    ctx.fillStyle = '#fbbf24'; ctx.fillRect(w*0.6, h*0.45, 50, 25);
    ctx.fillStyle = '#000'; ctx.font = 'bold 10px Inter'; ctx.fillText('BUS', w*0.62, h*0.58);

    // Violating car
    if (STATE.ps124.violationCount > 0) {
      const cx = w * 0.25 + Math.sin(STATE.simTick * 0.2) * 20;
      ctx.fillStyle = '#dc2626'; ctx.fillRect(cx, h*0.47, 35, 18);
      ctx.strokeStyle = '#f87171'; ctx.lineWidth = 1.5; ctx.strokeRect(cx - 2, h*0.45, 39, 22);
      ctx.fillStyle = 'rgba(248,113,113,0.8)'; ctx.fillRect(cx, h*0.43 - 10, 60, 10);
      ctx.fillStyle = '#fff'; ctx.font = 'bold 7px Inter'; ctx.fillText(' VIOLATION', cx + 2, h*0.43 - 3);
    }

    // Top HUD
    ctx.fillStyle = 'rgba(0,0,0,0.6)'; ctx.fillRect(0, 0, w, 18);
    ctx.fillStyle = '#fbbf24'; ctx.font = 'bold 9px JetBrains Mono'; ctx.fillText(`* REC  BUS-DTC-419  BRTS ENFORCEMENT`, 8, 12);
  });
}

function drawAQIChart(targetId) {
  const canvasIds = targetId ? [targetId] : ['ps124-aqi-chart', 'ps124-aqi-chart-pane'];
  canvasIds.forEach(id => {
    const canvas = document.getElementById(id);
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    const w = canvas.width, h = canvas.height;
    ctx.clearRect(0, 0, w, h);
    ctx.fillStyle = 'rgba(10,14,23,0.9)'; ctx.fillRect(0, 0, w, h);

    // AQI bands
    const bands = [
      { max: 50, color: 'rgba(52,211,153,0.1)', label: 'Good' },
      { max: 100, color: 'rgba(251,191,36,0.1)', label: 'Moderate' },
      { max: 150, color: 'rgba(251,146,60,0.1)', label: 'Unhealthy' },
    ];
    bands.forEach((band, i) => {
      const y1 = h - (band.max / 200) * h;
      const y0 = i > 0 ? h - (bands[i-1].max / 200) * h : h;
      ctx.fillStyle = band.color;
      ctx.fillRect(0, y1, w, y0 - y1);
    });

    // PM2.5 line
    const pm25 = STATE.ps124.pm25History;
    if (pm25.length >= 2) {
      ctx.strokeStyle = '#34d399'; ctx.lineWidth = 1.5;
      ctx.beginPath();
      pm25.forEach((val, i) => {
        const x = (i / (pm25.length - 1)) * w;
        const y = h - (val / 200) * h;
        if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
      });
      ctx.stroke();
    }

    // PM10 line
    const pm10 = STATE.ps124.pm10History;
    if (pm10.length >= 2) {
      ctx.strokeStyle = '#818cf8'; ctx.lineWidth = 1;
      ctx.beginPath();
      pm10.forEach((val, i) => {
        const x = (i / (pm10.length - 1)) * w;
        const y = h - (val / 200) * h;
        if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
      });
      ctx.stroke();
    }

    // Legend
    ctx.fillStyle = '#34d399'; ctx.fillRect(w - 80, 5, 8, 3);
    ctx.fillStyle = '#94a3b8'; ctx.font = '7px Inter'; ctx.fillText('PM2.5', w - 68, 9);
    ctx.fillStyle = '#818cf8'; ctx.fillRect(w - 80, 13, 8, 3);
    ctx.fillStyle = '#94a3b8'; ctx.fillText('PM10', w - 68, 17);
  });
}

// ========================= UTILITY =========================
function getCameraName(camId) {
  const fixed = FIXED_CAMERAS.find(c => c.id === camId);
  if (fixed) return fixed.name;
  const bus = BUS_ROUTES.find(b => b.id === camId);
  if (bus) return bus.name;
  return 'Node';
}

function generateHash(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) { hash = ((hash << 5) - hash) + str.charCodeAt(i); hash |= 0; }
  return Math.abs(hash).toString(16).padStart(8, '0') + '9f4a1c2e8b7d03a1fc65471829e0da76'.slice(0, 24);
}

function haversine(lat1, lon1, lat2, lon2) {
  const R = 6371;
  const dLat = (lat2 - lat1) * Math.PI / 180;
  const dLon = (lon2 - lon1) * Math.PI / 180;
  const a = Math.sin(dLat / 2) ** 2 + Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) * Math.sin(dLon / 2) ** 2;
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}

